type AppContext={refresh:()=>void,act:(fn:()=>Promise<any>,message?:string)=>Promise<any>,openWizard:(channel?:string,source?:string)=>void};
const Context=React.createContext<AppContext>({refresh:()=>{},act:async()=>{},openWizard:()=>{}});
const useApp=()=>React.useContext(Context);
function useData(path:string,version=0,poll=0){
  const [data,setData]=useState<any>(null),[error,setError]=useState('');
  useEffect(()=>{let alive=true;const load=()=>api(path).then(d=>{if(alive){setData(d);setError('')}}).catch(e=>alive&&setError(e.message));load();const timer=poll?setInterval(()=>{if(!document.hidden)load()},poll):null;return()=>{alive=false;if(timer)clearInterval(timer)}},[path,version,poll]);
  return {data,error};
}
function LanguagePicker(){
  const language=useInterfaceLanguage();
  return <label className="interface-language"><span>{tr('Interface language')}</span><select aria-label={tr('Interface language')} value={language} onChange={event=>setInterfaceLanguage(event.target.value==='vi'?'vi':'en')}><option value="en" lang="en">English</option><option value="vi" lang="vi">Tiếng Việt</option></select></label>;
}
function Loading({error}:{error?:string}){return error?<div role="alert" className="notice error">{error}<Button small onClick={()=>location.reload()}>{tr("Retry")}</Button></div>:<div className="loading"><Loader2 className="spin"/> {tr("Opening workspace…")}</div>}
function App(){
  useInterfaceLanguage();
  const [route,setRoute]=useState(location.hash.slice(1)||'/channels'),[revision,setRevision]=useState(0),[toast,setToast]=useState<{text:string,error?:boolean}|null>(null),[busy,setBusy]=useState(false),[wizard,setWizard]=useState<{channel?:string,source?:string}|null>(null),[channelModal,setChannelModal]=useState(false),[mobile,setMobile]=useState(false);
  const {data:dashboard,error}=useData('/dashboard',revision,4000);
  const {data:channels}=useData('/channels',revision,6000);
  useEffect(()=>{const handler=()=>{const next=location.hash.slice(1)||'/channels';setRoute(next);setMobile(false);window.scrollTo(0,0);localStorage.setItem('storyforge-route',next)};window.addEventListener('hashchange',handler);return()=>window.removeEventListener('hashchange',handler)},[]);
  useEffect(()=>{if(!mobile)return;const close=(event:KeyboardEvent)=>{if(event.key==='Escape'){setMobile(false);document.querySelector<HTMLButtonElement>('.mobile-menu')?.focus()}};window.addEventListener('keydown',close);return()=>window.removeEventListener('keydown',close)},[mobile]);
  useEffect(()=>{if(toast){const timer=setTimeout(()=>setToast(null),6000);return()=>clearTimeout(timer)}},[toast]);
  const refresh=useCallback(()=>setRevision(v=>v+1),[]);
  const act=useCallback(async(fn:()=>Promise<any>,message='Saved')=>{setBusy(true);try{const result=await fn();setToast({text:result?.checkpoint||result?.message||message});refresh();return result}catch(e){setToast({text:(e as Error).message,error:true});throw e}finally{setBusy(false)}},[refresh]);
  // Event actions report their errors via the central toast, without unhandled rejections.
  const safeAct=useCallback((fn:()=>Promise<any>,message?:string)=>act(fn,message).catch(()=>undefined),[act]);
  const parts=route.split('/').filter(Boolean),section=parts[0]||'channels';
  const nav=[['channels','Channels',LayoutGrid],['projects','All projects',Clapperboard],['inbox','Content inbox',Inbox],['library','Source library',BookOpen],['calendar','Content calendar',CalendarDays],['analytics','Analytics',Activity],['novelty','Novelty memory',GitBranch]] as const;
  return <Context.Provider value={{refresh,act:safeAct,openWizard:(channel,source)=>setWizard({channel,source})}}><a className="skip-link" href="#main" onClick={event=>{event.preventDefault();document.getElementById('main')?.focus()}}>{tr("Skip to content")}</a><div className={'app '+(mobile?'nav-open':'')}>
    {mobile&&<button className="nav-backdrop" aria-label={tr("Close navigation")} onClick={()=>setMobile(false)}/>}<aside className="sidebar" onClick={event=>{if((event.target as HTMLElement).closest('a'))setMobile(false)}}><a href="#/channels" className="brand"><img src="/brand.png" alt={tr("")} width="42" height="42"/><div><strong>{tr("StoryForge")}<span>{tr("US")}</span></strong><span className="brand-version">v{appInfo.version}</span><small>{tr("THE STORY PRODUCTION STUDIO")}</small></div></a><div className="workspace-label"><div className="workspace-avatar"><Mountain size={18}/></div><div><strong>{tr("My workspace")}</strong><small>{tr("Local · Private · Yours")}</small></div><LockKeyhole size={13}/></div><div className="nav-label">{tr("WORKSPACE")}</div><nav>{nav.map(([key,title,Icon])=><a key={key} href={'#/'+key} className={section===key?'selected':''}><Icon size={18}/><span>{tr(title)}</span>{key==='inbox'&&dashboard?.sources>0&&<em>{dashboard.sources}</em>}</a>)}</nav><div className="nav-label inline between">{tr("YOUR CHANNELS")}<button className="icon-button" aria-label={tr("Create channel")} onClick={()=>setChannelModal(true)}><Plus size={14}/></button></div><nav className="channel-nav">{channels?.items.map((c:Row)=><a href={'#/channels/'+c.id} key={c.id} className={parts[1]===c.id?'selected':''}><span className={'channel-dot '+c.color}/><span>{c.name}</span></a>)}{!channels?.items.length&&<p className="muted sidebar-hint">{tr("Your channels will appear here.")}</p>}</nav><div className="sidebar-bottom"><LanguagePicker/><div className="local-card"><div className="inline"><span className="online-dot"/><strong>{tr("Local engine online")}</strong></div><p>{tr("Your ideas stay on this device.")}</p></div><nav><a href={'#/jobs'+(section==='projects'&&parts[1]?'/'+parts[1]:'')} className={section==='jobs'?'selected':''}><ListChecks size={18}/>{tr("Activity & jobs")}{dashboard?.active_jobs>0&&<em>{dashboard.active_jobs}</em>}</a><a href="#/settings" className={section==='settings'?'selected':''}><Settings2 size={18}/>{tr("Settings")}</a><a href="#/logs" className={section==='logs'?'selected':''}><TerminalSquare size={18}/>{tr("Logs & diagnostics")}</a></nav><div className="sidebar-footer"><span className="user-avatar">{tr("SF")}</span><div><strong>{tr("Creator workspace")}</strong><small>StoryForge US v{appInfo.version}</small></div><span className="version-tag">{tr("LOCAL")}</span></div></div></aside>
    <div className="workspace"><header className="topbar"><div className="inline"><button className="icon-button mobile-menu" aria-label={tr("Toggle navigation")} aria-expanded={mobile} onClick={()=>setMobile(!mobile)}><Menu size={20}/></button><span className="muted">{tr("Workspace")}</span><ChevronRight size={14}/><span>{label(section)}</span>{parts.length>1&&<><ChevronRight size={14}/><span className="muted">{tr("Studio")}</span></>}</div><div className="inline"><Badge tone={dashboard?.settings.provider_mode==='mock'?'amber':'blue'}>{dashboard?.settings.provider_mode==='mock'?tr("Mock provider"):tr("Browser providers")}</Badge><a className="top-help" href="#/settings/bridge"><CircleHelp size={17}/> {tr("Setup guide")}</a><span className="avatar-small">{tr("SF")}</span></div></header>
    <main id="main" tabIndex={-1} key={section}>
      {!dashboard?<Loading error={error}/>:section==='channels'?(parts[1]?<ChannelDetail id={parts[1]} version={revision}/>:<Channels data={dashboard} channels={channels?.items||[]} onNew={()=>setChannelModal(true)}/>):section==='projects'?(parts[1]?<ProjectStudio id={parts[1]} tab={parts[2]||'overview'} version={revision}/>:<Projects version={revision}/>):section==='inbox'||section==='library'?(parts[1]?<SourceDetail id={parts[1]} version={revision}/>:<Sources version={revision} library={section==='library'}/>):section==='jobs'?<Jobs version={revision} returnProjectId={parts[1]}/>:section==='calendar'?<Calendar version={revision}/>:section==='analytics'?<Analytics version={revision}/>:section==='novelty'?<Novelty version={revision}/>:section==='settings'?<Settings version={revision} initialTab={parts[1]}/>:section==='logs'?<Logs version={revision}/>:<Empty title={tr("Page not found")} description={tr("Return to your channel workspace.")} action={<a className="button" href="#/channels">{tr("Open channels")}</a>}/>}
    </main><footer className="workspace-footer"><span><LockKeyhole size={12}/> {tr("Stored locally with SQLite")}</span><span>{tr("From an idea to a story worth hearing.")}</span></footer></div>
    {toast&&<div role={toast.error?'alert':'status'} className={'toast '+(toast.error?'toast-error':'')}><span>{toast.error?<CircleHelp size={18}/>:<CheckCircle2 size={18}/>}</span>{tr(toast.text)}<button aria-label={tr("Dismiss notification")} onClick={()=>setToast(null)}><X size={16}/></button></div>}{busy&&<div className="top-loading"/>}
    {channelModal&&<ChannelForm onClose={()=>setChannelModal(false)}/>} {wizard&&<ProjectWizard {...wizard} onClose={()=>setWizard(null)}/>}
  </div></Context.Provider>
}

function Channels({data,channels,onNew}:{data:Row,channels:Row[],onNew:()=>void}){
  const {act,openWizard}=useApp();const [filter,setFilter]=useState('All channels'),[query,setQuery]=useState('');
  const shown=channels.filter(c=>(filter==='All channels'||c.status===(filter==='Established'?'ESTABLISHED':'DISCOVERY'))&&c.name.toLowerCase().includes(query.toLowerCase()));
  return <><PageHead eyebrow={tr("YOUR CREATIVE HOME")} title={tr("Every channel. A world of its own.")} description={tr("Shape your channels, discover your next story, and bring it to life.")} action={<Button primary onClick={onNew}><Plus size={17}/>{tr("New channel")}</Button>}/>
  <div className="stats-grid"><Stat label={tr("Your channels")} value={data.channels.toString().padStart(2,'0')} icon={<LayoutGrid size={17}/>} note="Distinct voices, one workspace"/><Stat label={tr("Stories in progress")} value={data.projects.toString().padStart(2,'0')} icon={<BookOpen size={17}/>} note="From first premise to final cut"/><Stat label={tr("Stories locked")} value={data.locked.toString().padStart(2,'0')} icon={<ShieldCheck size={17}/>} note="Quality gates passed"/><Stat label={tr("Ideas collected")} value={data.sources.toString().padStart(2,'0')} icon={<Inbox size={17}/>} note="In your source library"/></div>
  <div className="section-toolbar"><div className="tabs">{['All channels','Established','Discovery'].map(f=><button className={filter===f?'active':''} onClick={()=>setFilter(f)} key={tr(f)}>{tr(f)}{f==='All channels'&&<span>{channels.length}</span>}</button>)}</div><div className="search-field"><Search size={16}/><input aria-label={tr("Search channels")} placeholder={tr("Find a channel…")} value={query} onChange={e=>setQuery(e.target.value)}/></div></div>
  <div className="channel-grid">{shown.map(c=><article className="channel-card" key={c.id}><a className="channel-cover" href={'#/channels/'+c.id}><MountainArt variant={c.color}/><div className="cover-label"><Badge tone={c.status==='DISCOVERY'?'amber':'green'}>{c.status==='DISCOVERY'?tr("Discovery mode"):tr("Established")}</Badge>{c.is_demo&&<span className="demo-tag">{tr("DEMO")}</span>}</div><span className="cover-initial">{c.name.split(' ').map((s:string)=>s[0]).slice(0,2).join('')}</span></a><div className="channel-card-body"><div className="inline between"><h2>{c.name}</h2><span className={'channel-dot '+c.color}/></div><p>{c.niche||tr("Your next niche starts here")}</p><div className="channel-facts"><span><Globe2 size={13}/>{c.country==='United States'?tr("US audience"):c.country}</span><span><Clock3 size={13}/>{c.default_duration} {tr("min")}</span></div><div className="channel-card-stats"><div><strong>{c.project_count}</strong><span>{tr("Projects")}</span></div><div><strong>{c.published_count}</strong><span>{tr("Published")}</span></div><div><strong>{c.locked_count}</strong><span>{tr("Locked")}</span></div></div><div className="card-bottom"><span className="muted">{tr("Updated ")}{new Date(c.updated_at).toLocaleDateString('en-US',{month:'short',day:'numeric'})}</span><a className="text-link" href={'#/channels/'+c.id}>{tr("Open channel")}<ArrowRight size={15}/></a></div></div></article>)}<button className="new-channel-card" onClick={onNew}><span className="new-channel-icon"><Plus size={25}/></span><strong>{tr("A new voice. A new world.")}</strong><span>{tr("Build a channel around your niche,")}<br/>{tr("or discover one from your ideas.")}</span><em>{tr("Create a channel")}<ArrowRight size={15}/></em></button></div>
  {!channels.length&&<div className="notice"><Sparkles size={20}/><div><strong>{tr("Explore a complete sample workspace")}</strong><p>{tr("Three demo channels and original source fixtures. No fabricated YouTube analytics.")}</p></div><Button onClick={()=>act(()=>api('/demo','POST'),'Demo workspace loaded')}>{tr("Load demo workspace")}<ArrowRight size={15}/></Button></div>}
  <div className="two-col dashboard-bottom"><Section title={tr("Pick up where you left off")} caption={tr("Your most recently updated stories")} action={<a className="text-link" href="#/projects">{tr("View all")}<ArrowRight size={14}/></a>}>{data.recent_projects.length?<div className="project-list">{data.recent_projects.map((p:Row,i:number)=><a href={'#/projects/'+p.id} className="project-row" key={p.id}><span className={'project-glyph color-'+['blue','amber','violet'][i%3]}><FileText size={19}/></span><div><strong>{p.title}</strong><span>{channels.find(c=>c.id===p.channel_id)?.name} · {p.target_minutes} {tr("minute story")}</span></div><Status value={p.stage}/><ChevronRight size={17}/></a>)}</div>:<Empty title={tr("The first page is yours")} description={tr("Create a channel, then start your first story project.")}/>}</Section><Section title={tr("Your production path")} caption={tr("A considered process, from source to screen")} className="path-panel"><div className="production-path">{[[Inbox,'Collect & discover','Find the idea worth exploring'],[WandSparkles,'Write & refine','Build an original, consistent story'],[ShieldCheck,'Review & lock','Two models. One coherent story.'],[Clapperboard,'Produce & publish','Audio, visuals, and the final cut']].map(([Icon,title,text]:any,i)=><div className="path-step" key={tr(title)}><span className="path-number"><Icon size={17}/></span><div><strong>{tr(title)}</strong><small>{tr(text)}</small></div><span className="path-index">0{i+1}</span></div>)}</div><a href="#/settings/bridge" className="path-link">{tr("Connect your creative tools")}<ArrowRight size={15}/></a></Section></div></>
}

function ChannelForm({onClose}:{onClose:()=>void}){
  const {act}=useApp();const [form,setForm]=useState({name:'',status:'ESTABLISHED',niche:'',country:'United States',age_range:'25–54',language:'English (US)',default_duration:10,color:'blue'});const set=(k:string,v:any)=>setForm({...form,[k]:v});
  return <Modal title={tr("Create your channel")} onClose={onClose}><form onSubmit={async e=>{e.preventDefault();const result=await act(()=>api('/channels','POST',form),'Channel created');if(result){onClose();navigate('/channels/'+result.id)}}}><p className="form-intro">{tr("Give your stories a home and a voice of their own.")}</p><Field label={tr("Channel name")}><input required autoFocus maxLength={160} value={form.name} onChange={e=>set('name',e.target.value)} placeholder={tr("e.g. Midnight Archive")}/></Field><div className="choice-grid">{[['ESTABLISHED','I know my niche','Build on a clear content direction'],['DISCOVERY','Help me discover it','Explore sources and test ideas']].map(([value,title,description])=><button className={'choice '+(form.status===value?'chosen':'')} type="button" key={value} onClick={()=>set('status',value)}><span className="inline"><Dna size={19}/><strong>{tr(title)}</strong></span><small>{tr(description)}</small></button>)}</div>{form.status==='ESTABLISHED'&&<Field label={tr("Primary niche")}><input required value={form.niche} onChange={e=>set('niche',e.target.value)} placeholder={tr("Atmospheric mystery, survival…")}/></Field>}<div className="form-grid"><Field label={tr("Audience country")}><input value={form.country} onChange={e=>set('country',e.target.value)}/></Field><Field label={tr("Audience age range")}><input value={form.age_range} onChange={e=>set('age_range',e.target.value)}/></Field><Field label={tr("Narration language")}><input value={form.language} onChange={e=>set('language',e.target.value)}/></Field><Field label={tr("Default duration")}><select value={form.default_duration} onChange={e=>set('default_duration',+e.target.value)}>{[5,10,20,30,45,60].map(v=><option value={v} key={v}>{v} {tr("minutes")}</option>)}</select></Field></div><Field label={tr("Channel color")}><div className="color-options">{['blue','amber','violet','teal'].map(c=><button type="button" key={c} aria-label={c} aria-pressed={form.color===c} className={'swatch '+c+(form.color===c?' picked':'')} onClick={()=>set('color',c)}>{form.color===c&&<Check size={16}/>}</button>)}</div></Field><div className="modal-actions"><Button type="button" onClick={onClose}>{tr("Cancel")}</Button><Button primary type="submit"><Plus size={16}/>{tr("Create channel")}</Button></div></form></Modal>
}

function ChannelDetail({id,version}:{id:string,version:number}){
  const {data:c,error}=useData('/channels/'+id,version,3500);const {act,openWizard}=useApp();const [tab,setTab]=useState('Overview'),[selectedVersion,setSelectedVersion]=useState('');
  if(!c)return <Loading error={error}/>;
  const discovery=c.discovery?.[0]?.content;
  return <><a className="back-link" href="#/channels"><ArrowLeft size={14}/>{tr("All channels")}</a><PageHead eyebrow={tr("CHANNEL STUDIO")} title={c.name} description={c.niche} action={<><Status value={c.status}/><Button primary onClick={()=>openWizard(id)}><Plus size={17}/>{tr("New project")}</Button></>}/><div className="tabs page-tabs">{['Overview','Channel DNA','Discovery','Versions'].map(t=><button key={tr(t)} className={tab===t?'active':''} onClick={()=>setTab(t)}>{tr(t)}</button>)}<a href={'/api/channels/'+id+'/export'} className="tab-end"><Download size={14}/>{tr("Export channel")}</a></div>
  {tab==='Overview'&&<><div className="stats-grid"><Stat label={tr("Projects")} value={c.projects.length}/><Stat label={tr("Source pool")} value={c.sources.length}/><Stat label={tr("Observed videos")} value={c.learning.sample_size}/><Stat label={tr("Evidence level")} value={c.learning.confidence}/></div><Section title={tr("Your stories")} action={<Button small onClick={()=>openWizard(id)}><Plus size={14}/>{tr("New project")}</Button>}><ProjectTable projects={c.projects}/></Section><div className="two-col"><Section title={tr("Channel identity")}><Readable value={{audience:c.country,language:c.language,duration:c.default_duration+' minutes',tone:c.dna.tone}}/></Section><Section title={tr("Learning from your audience")} caption={tr("Observed performance, with sample size")}><Readable value={c.learning}/></Section></div></>}
  {tab==='Channel DNA'&&<Section title={tr("The voice behind every story")} caption={tr("Manual edits are versioned. AI recommendations are never applied silently.")}><JsonEditor value={c.dna} title={tr("Channel DNA")} onSave={async dna=>act(()=>api('/channels/'+id+'/dna','POST',{dna,note:'Manual edit from Channel DNA'}),'Channel DNA version saved')}/><div className="notice compact"><ShieldCheck size={18}/><span>{tr("High-impact changes should be tested on a small set of videos before adoption.")}</span></div></Section>}
  {tab==='Discovery'&&<><Section title={tr("Find a direction worth exploring")} caption={tr("Sources → abstract story DNA → clusters → testable hypotheses")} action={<Button primary disabled={!c.sources.length} title={!c.sources.length?tr("Assign sources to this channel first"):''} onClick={()=>act(()=>api('/jobs','POST',{kind:'discovery',channel_id:id}),'Discovery job queued')}><Sparkles size={16}/>{tr("Generate hypotheses")}</Button>}><div className="notice compact">{tr("Heuristic scores help compare ideas. They are not YouTube demand or performance data.")}</div>{!c.sources.length&&<Empty title={tr("Start with a few sources")} description={tr("Add source text in Content inbox and assign it to this channel.")} action={<a className="button" href="#/inbox">{tr("Open inbox")}<ArrowRight size={15}/></a>}/>}<div className="hypothesis-grid">{discovery?.hypotheses?.map((h:Row,i:number)=><article className="hypothesis" key={h.name}><div className="eyebrow">{tr("HYPOTHESIS 0")}{i+1}</div><h3>{h.name}</h3><p>{h.genres.join(' · ')}</p>{Object.entries(h.scores).map(([k,v]:any)=><div className="score-row" key={k}><span>{label(k)}</span><Progress value={v}/><strong>{v}</strong></div>)}<div className="stack-actions"><Button onClick={()=>{const count=Number(window.prompt(tr("Videos to plan for this hypothesis"),'5'));if(count>0)act(()=>api('/channels/'+id+'/test-plan','POST',{hypothesis:h.name,count}),'Test plan added to calendar')}}><CalendarDays size={15}/>{tr("Create test plan")}</Button><Button primary onClick={()=>act(()=>api('/channels/'+id+'/dna','POST',{dna:{...c.dna,primary_genres:h.genres},establish:true,note:'User accepted discovery hypothesis: '+h.name,magnitude:'HIGH'}),'Channel DNA established')}>{tr("Establish this DNA")}<Check size={15}/></Button></div></article>)}</div></Section><Section title={tr("Observed response")} caption={tr("{p0} videos with manual analytics · {p1} evidence",{p0:c.learning.sample_size,p1:c.learning.confidence})}><Readable value={c.learning}/></Section></>}
  {tab==='Versions'&&<Section title={tr("Channel DNA history")}><div className="version-list">{c.dna_versions.map((v:Row)=><div key={v.id}><div className="inline between"><div><strong>{tr("Version ")}{v.version}</strong><p>{v.note} · {new Date(v.created_at).toLocaleString()}</p></div><Status value={v.status}/><Button small onClick={()=>setSelectedVersion(selectedVersion===v.id?'':v.id)}>{tr("View diff")}</Button></div>{selectedVersion===v.id&&<div className="two-col compare"><div><h3>{tr("Current DNA")}</h3><pre>{pretty(c.dna)}</pre></div><div><h3>{tr("Version ")}{v.version} · {v.magnitude} {tr("change")}</h3><pre>{pretty(v.dna)}</pre><div className="inline">{['accepted','testing','rejected'].map(status=><Button key={status} small onClick={()=>act(()=>api('/channels/'+id+'/dna','POST',{dna:v.dna,status,magnitude:v.magnitude,note:'Decision on version '+v.version}),label(status))}>{status==='accepted'?tr("Accept"):status==='testing'?tr("Test first"):tr("Reject")}</Button>)}</div></div></div>}</div>)}</div></Section>}</>
}

function ProjectTable({projects,selection,onDeleted}:{projects:Row[],selection?:ReturnType<typeof usePageSelection>,onDeleted?:()=>void}){return projects.length?<div className="table-wrap"><table><thead><tr>{selection&&<th aria-label={tr("Selection")}/>}<th>{tr("Story project")}</th><th>{tr("Target duration")}</th><th>{tr("Stage")}</th><th>{tr("Version")}</th><th/></tr></thead><tbody>{projects.map(p=><tr key={p.id}>{selection&&<td><input type="checkbox" aria-label={tr("Select ")+p.title} checked={selection.ids.includes(p.id)} onChange={()=>selection.toggle(p.id)}/></td>}<td><a className="table-title" href={'#/projects/'+p.id}><FileText size={17}/>{p.title}</a>{p.is_demo&&<small className="muted">{tr("Demo project")}</small>}</td><td><Clock3 size={13}/> {p.target_minutes} {tr("min")}</td><td><Status value={p.stage}/></td><td>{p.story_version?tr("v")+p.story_version+'.0':'—'}</td><td><div className="inline wrap"><a className="text-link" href={'#/projects/'+p.id}>{tr("Open")}<ArrowRight size={14}/></a>{selection&&onDeleted&&<DeletionButton kind="projects" ids={[p.id]} title={p.title} onDeleted={onDeleted}/>}</div></td></tr>)}</tbody></table></div>:<Empty title={tr("Your next story starts here")} description={tr("Create a project to turn an idea into a complete production.")}/>}
function Projects({version}:{version:number}){
  const [page,setPage]=useState(0);const {data,error}=useData('/projects?offset='+page*50,version,5000);const {openWizard,refresh}=useApp();const selection=usePageSelection(data?.items);
  const deleted=()=>{selection.clear();setPage(0);refresh()};
  return <><PageHead eyebrow={tr("PRODUCTION LIBRARY")} title={tr("Stories in the making")} description={tr("Every project, from the first spark to the final frame.")} action={<Button primary onClick={()=>openWizard()}><Plus size={17}/>{tr("New project")}</Button>}/><BulkToolbar kind="projects" selection={selection} count={data?.items.length||0} onDeleted={deleted}/><Section>{data?<ProjectTable projects={data.items} selection={selection} onDeleted={deleted}/>:<Loading error={error}/>}</Section><ListPagination page={page} total={data?.total||0} onChange={next=>{selection.clear();setPage(next)}}/></>
}
function ProjectWizard({channel,source,onClose}:{channel?:string,source?:string,onClose:()=>void}){
  const {data:channels}=useData('/channels'),{data:sources}=useData('/sources');const {act}=useApp();
  const [step,setStep]=useState(1),[form,setForm]=useState({title:'',channel_id:channel||'',source_id:source||'',duration_mode:'10',target_minutes:10,wpm:150});
  const {data:profile}=useData(`/duration?minutes=${form.target_minutes}&wpm=${form.wpm}`);
  const set=(k:string,v:any)=>setForm(prev=>({...prev,[k]:v}));
  return <Modal title={tr("A new story begins")} onClose={onClose} wide><div className="wizard-steps">{['The idea','The shape','Ready to create'].map((s,i)=><span className={step===i+1?'active':step>i+1?'done':''} key={s}><b>{step>i+1?<Check size={13}/>:i+1}</b>{tr(s)}</span>)}</div><form onSubmit={async e=>{e.preventDefault();if(step<3){setStep(step+1);return}const result=await act(()=>api('/projects','POST',{...form,source_id:form.source_id||null}),'Project created');if(result){onClose();navigate('/projects/'+result.id)}}}>
  {step===1&&<><Field label={tr("Project title")}><input required autoFocus value={form.title} onChange={e=>set('title',e.target.value)} placeholder={tr("A working title for your next story")}/></Field><Field label={tr("Channel")}><select required value={form.channel_id} onChange={e=>{const selected=channels?.items.find((c:Row)=>c.id===e.target.value);setForm({...form,channel_id:e.target.value,target_minutes:selected?.default_duration||10,duration_mode:String(selected?.default_duration||10)})}}><option value="">{tr("Choose a channel")}</option>{channels?.items.map((c:Row)=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field>{channels?.items.length===0&&<p className="error-text">{tr("Create a channel first from the Channels page.")}</p>}<Field label={tr("Source inspiration (optional)")}><select value={form.source_id} onChange={e=>set('source_id',e.target.value)}><option value="">{tr("Start from an original idea")}</option>{sources?.items.map((s:Row)=><option key={s.id} value={s.id}>{s.title}</option>)}</select></Field></>}
  {step===2&&<><Field label={tr("Target duration")}><div className="duration-options">{['Auto','5','10','20','30','45','60','Custom'].map(v=><button type="button" className={form.duration_mode===v?'active':''} key={v} onClick={()=>setForm({...form,duration_mode:v,target_minutes:Number(v)||form.target_minutes})}>{tr(v)}{/^\d/.test(v)&&<small>{tr("min")}</small>}</button>)}</div></Field>{['Custom','Auto'].includes(form.duration_mode)&&<Field label={form.duration_mode==='Auto'?tr("Provisional duration · review the recommendation after premise selection"):tr("Custom minutes")}><input type="number" min="1" max="240" value={form.target_minutes} onChange={e=>set('target_minutes',+e.target.value)}/></Field>}<Field label={tr("Narration speed (words per minute)")}><input type="number" min="80" max="240" value={form.wpm} onChange={e=>set('wpm',+e.target.value)}/></Field>{profile&&<div className="duration-summary"><Stat label={tr("Word target")} value={profile.target_words.toLocaleString()} note={tr("{min}–{max} words",{min:profile.word_range[0],max:profile.word_range[1]})}/><Stat label={tr("Characters")} value={profile.characters.join('–')}/><Stat label={tr("Visual scenes")} value={profile.scenes.join('–')}/></div>}</>}
  {step===3&&<><div className="wizard-ready"><div className="empty-icon"><BookOpen size={28}/></div><h3>{form.title}</h3><p>{channels?.items.find((c:Row)=>c.id===form.channel_id)?.name} · {form.target_minutes} {tr("minutes · ")}{form.wpm} {tr("WPM")}</p></div><div className="notice compact"><ShieldCheck size={18}/><span>{tr("You choose the premise, approve Story Lock, and review the final video. These checkpoints are on by default.")}</span></div></>}
  <div className="modal-actions"><Button type="button" onClick={()=>step>1?setStep(step-1):onClose()}>{step>1?tr("Back"):tr("Cancel")}</Button><Button primary type="submit">{step===3?tr("Create project"):tr("Continue")}<ArrowRight size={16}/></Button></div></form></Modal>
}

function Sources({version,library=false}:{version:number,library?:boolean}){
  const {act,refresh}=useApp();const [query,setQuery]=useState(''),[modal,setModal]=useState(false),[selected,setSelected]=useState<string[]>([]),[page,setPage]=useState(0);
  const {data,error}=useData('/sources?q='+encodeURIComponent(query)+'&offset='+page*50,version,5000);
  return <><PageHead eyebrow={library?tr("YOUR INSPIRATION, ORGANIZED"):tr("COLLECT THE NEXT GREAT IDEA")} title={library?tr("Source library"):tr("Content inbox")} description={tr("Collect sources. Extract the motifs. Make something entirely your own.")} action={<><label className="button"><Upload size={16}/>{tr("Import TXT / MD / CSV")}<input type="file" hidden accept=".txt,.md,.csv" onChange={async e=>{if(e.target.files?.[0]){const body=new FormData();body.append('file',e.target.files[0]);await act(()=>api('/sources/import','POST',body),'Sources imported');e.target.value=''}}}/></label><Button primary onClick={()=>setModal(true)}><Plus size={17}/>{tr("Add source")}</Button></>}/><div className="section-toolbar"><span className="muted">{data?.total||0} {tr("sources in your workspace")}</span><div className="inline">{selected.length>0&&<Button onClick={()=>act(async()=>{for(const source_id of selected)await api('/jobs','POST',{kind:'story_dna',source_id});setSelected([])},'Analysis jobs queued')}><Sparkles size={15}/>{tr("Analyze ")}{selected.length}</Button>}{selected.length>0&&<DeletionButton kind="sources" ids={selected} onDeleted={()=>{setSelected([]);setPage(0);refresh()}}/>}<div className="search-field"><Search size={16}/><input aria-label={tr("Search sources")} placeholder={tr("Search sources…")} value={query} onChange={e=>{setQuery(e.target.value);setPage(0)}}/></div></div></div><Section>{!data?<Loading error={error}/>:data.items.length?<div className="table-wrap"><table><thead><tr><th><input type="checkbox" aria-label={tr("Select all sources")} checked={!!data.items.length&&selected.length===data.items.length} onChange={e=>setSelected(e.target.checked?data.items.map((s:Row)=>s.id):[])}/></th><th>{tr("Source")}</th><th>{tr("Language")}</th><th>{tr("Story DNA")}</th><th>{tr("Added")}</th><th/></tr></thead><tbody>{data.items.map((s:Row)=><tr key={s.id}><td><input aria-label={tr("Select ")+s.title} type="checkbox" checked={selected.includes(s.id)} onChange={e=>setSelected(e.target.checked?[...selected,s.id]:selected.filter(id=>id!==s.id))}/></td><td><a className="table-title" href={'#/inbox/'+s.id}><FileText size={17}/>{s.title}</a><small className="muted">{s.platform} · {s.tags.join(', ')||tr("No tags")}</small></td><td>{s.language}</td><td><Status value={Object.keys(s.dna).length?'ANALYZED':'PENDING'}/></td><td>{new Date(s.created_at).toLocaleDateString()}</td><td><div className="inline wrap"><a className="text-link" href={'#/inbox/'+s.id}>{tr("Explore")}<ArrowRight size={14}/></a><DeletionButton kind="sources" ids={[s.id]} title={s.title} onDeleted={()=>{setSelected(selected.filter(id=>id!==s.id));setPage(0);refresh()}}/></div></td></tr>)}</tbody></table></div>:<Empty title={tr("Great stories begin with curiosity")} description={tr("Add a URL with notes, paste a transcript, or import text. The app never scrapes protected content.")} action={<Button primary onClick={()=>setModal(true)}><Plus size={16}/>{tr("Add your first source")}</Button>}/>}</Section>{data?.total>50&&<div className="inline"><Button disabled={!page} onClick={()=>setPage(page-1)}>{tr("Previous")}</Button><span>{tr("Page ")}{page+1}</span><Button disabled={(page+1)*50>=data.total} onClick={()=>setPage(page+1)}>{tr("Next")}</Button></div>}{modal&&<SourceForm onClose={()=>setModal(false)}/>}</>
}
function SourceForm({onClose}:{onClose:()=>void}){const {act}=useApp();const {data:channels}=useData('/channels');const [form,setForm]=useState({title:'',url:'',summary:'',transcript:'',channel_id:'',language:'English',tags:''});const set=(k:string,v:any)=>setForm({...form,[k]:v});return <Modal title={tr("Add a source")} onClose={onClose} wide><form onSubmit={async e=>{e.preventDefault();const r=await act(()=>api('/sources','POST',{...form,tags:form.tags.split(',').map(s=>s.trim()).filter(Boolean),channel_id:form.channel_id||null,platform:form.url?'Web source':'Pasted text'}),'Source added');if(r){onClose();navigate('/inbox/'+r.id)}}}><div className="form-grid"><Field label={tr("Title")}><input required autoFocus value={form.title} onChange={e=>set('title',e.target.value)}/></Field><Field label={tr("Source URL (optional)")}><input type="url" value={form.url} onChange={e=>set('url',e.target.value)} placeholder={tr("https://…")}/></Field></div><Field label={tr("Transcript / original text")} hint={tr("Paste content you have permission to use. Story DNA extracts abstract motifs.")}><textarea rows={7} value={form.transcript} onChange={e=>set('transcript',e.target.value)}/></Field><Field label={tr("Summary / notes")}><textarea rows={3} value={form.summary} onChange={e=>set('summary',e.target.value)}/></Field><div className="form-grid"><Field label={tr("Assign channel")}><select value={form.channel_id} onChange={e=>set('channel_id',e.target.value)}><option value="">{tr("Keep in global inbox")}</option>{channels?.items.map((c:Row)=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Field label={tr("Tags (comma separated)")}><input value={form.tags} onChange={e=>set('tags',e.target.value)}/></Field></div><div className="modal-actions"><Button onClick={onClose} type="button">{tr("Cancel")}</Button><Button primary type="submit">{tr("Add source")}<ArrowRight size={16}/></Button></div></form></Modal>}
function SourceDetail({id,version}:{id:string,version:number}){const {data:s,error}=useData('/sources/'+id,version,3500);const {data:channels}=useData('/channels');const {act,openWizard}=useApp();const [tab,setTab]=useState('Source');if(!s)return <Loading error={error}/>;return <><a className="back-link" href="#/inbox"><ArrowLeft size={14}/>{tr("Content inbox")}</a><PageHead eyebrow={tr("SOURCE INTELLIGENCE")} title={s.title} description={s.url||s.platform} action={<><Button onClick={()=>act(()=>api('/jobs','POST',{kind:'story_dna',source_id:id}),'Story DNA analysis queued')}><Sparkles size={16}/>{tr("Analyze Story DNA")}</Button><Button primary onClick={()=>openWizard(s.channel_id,id)}><Plus size={16}/>{tr("Create adaptation")}</Button></>}/><div className="tabs page-tabs">{['Source','Story DNA','Channel fit'].map(t=><button className={tab===t?'active':''} onClick={()=>setTab(t)} key={tr(t)}>{tr(t)}</button>)}</div>{tab==='Source'&&<Section title={tr("Source material")}><SourceTranslation source={s}/><JsonEditor value={{title:s.title,url:s.url,transcript:s.transcript,summary:s.summary,notes:s.notes,tags:s.tags,language:s.language,channel_id:s.channel_id}} onSave={v=>act(()=>api('/sources/'+id,'PATCH',v),'Source updated')}/></Section>}{tab==='Story DNA'&&<Section title={tr("Abstract patterns. Original possibilities.")} caption={tr("The source-specific details below are explicitly excluded from adaptation.")}>{Object.keys(s.dna).length?<JsonEditor value={s.dna} onSave={dna=>act(()=>api('/sources/'+id,'PATCH',{dna}),'Story DNA saved')}/>:<Empty title={tr("Understand what makes this story work")} description={tr("Run Story DNA analysis using mock fixtures or the Gemini browser bridge.")}/>}{s.raw_result&&<details><summary>{tr("Raw provider output")}</summary><pre>{s.raw_result}</pre></details>}</Section>}{tab==='Channel fit'&&<Section title={tr("Find the right home")} caption={tr("Local heuristic based on motifs, channel DNA, history and content calendar.")}>{s.fits.map((fit:Row)=><div className="fit-row" key={fit.channel_id}><div className="fit-score">{fit.score}<small>/100</small></div><div><h3>{fit.channel_name}</h3><p>{fit.reasons.join(' · ')}</p>{fit.conflicts.length>0&&<p className="error-text">{fit.conflicts.join(' · ')}</p>}<small className="muted">{fit.adaptation_opportunity}</small></div><div className="stack-actions"><Button small onClick={()=>act(()=>api('/sources/'+id,'PATCH',{channel_id:fit.channel_id,status:'ASSIGNED'}),'Source assigned')}>{tr("Assign channel")}</Button><Button small onClick={()=>openWizard(fit.channel_id,id)}>{tr("New adaptation")}</Button></div></div>)}{!s.fits.length&&<Empty title={tr("Analyze the source first")} description={tr("Story DNA makes channel comparisons possible.")}/>}<div className="inline"><Button small onClick={()=>act(()=>api('/sources/'+id,'PATCH',{channel_id:null,status:'INBOX'}),'Kept in inbox')}>{tr("Keep in inbox")}</Button><small className="muted">{tr("Each multi-channel adaptation gets its own project, direction and novelty checks.")}</small></div></Section>}</>}

const studioTabs=[['overview','Overview',LayoutGrid],['direction','Direction',Dna],['premises','Premises',Sparkles],['bible','Story Bible',BookOpen],['outline','Outline',Layers3],['draft','Draft',FileText],['audit','Story audit',ShieldCheck],['versions','Story lock',LockKeyhole],['tts','TTS studio',AudioLines],['visuals','Visual director',Image],['assets','Assets',FolderOpen],['timeline','Timeline',Activity],['render','Render & QA',Clapperboard],['publish','Publish',Globe2]] as const;
function ProjectStudio({id,tab,version}:{id:string,tab:string,version:number}){
  const {data:p,error}=useData('/projects/'+id,version,2500);const {act}=useApp();const [issue,setIssue]=useState<Row|null>(null);const [productionValidation,setProductionValidation]=useState<Row|null>(null);
  if(!p)return <Loading error={error}/>;
  const active=p.jobs.find((j:Row)=>['queued','running','waiting_user'].includes(j.status));
  const run=(kind:string,payload:Row={})=>act(()=>api('/jobs','POST',{kind,project_id:id,payload}),tr('{step} queued',{step:label(kind)}));
  const artifact=(kind:string)=>p.artifacts[kind]?.content;
  const action=(kind:string,text:string,primary=false)=><Button primary={primary} disabled={!!active} title={active?tr("Finish the active job first"):''} onClick={()=>run(kind)}><Sparkles size={15}/>{tr(text)}</Button>;
  return <ViewTranslationScope key={id} active={!['overview','publish'].includes(tab)}><a className="back-link" href={'#/channels/'+p.channel_id}><ArrowLeft size={14}/>{p.channel.name}</a><PageHead eyebrow={tr("PROJECT STUDIO")+(p.is_demo?' · DEMO':'')} title={p.title} description={tr("{p0} minute story · {p1} WPM · {p2}",{p0:p.target_minutes,p1:p.wpm,p2:p.story_version?tr('Version')+' '+p.story_version+'.0':tr('No draft yet')})} action={<><Status value={p.locked?'LOCKED':p.stage}/><Button primary disabled={!!active} onClick={async()=>{const result=await act(()=>api('/projects/'+id+'/pipeline','POST'),'Pipeline started');setProductionValidation(result?.validation||null)}}><Play size={16}/>{tr("Continue pipeline")}</Button></>}/>
  {productionValidation&&<Modal title={tr("Check uploaded resources")} onClose={()=>setProductionValidation(null)}><ProductionValidation value={productionValidation} projectId={id}/><div className="modal-actions"><Button onClick={()=>setProductionValidation(null)}>{tr("Close")}</Button></div></Modal>}
  <div className="studio-layout"><nav className="studio-nav" aria-label={tr("Project stages")}>{studioTabs.map(([key,title,Icon],i)=><React.Fragment key={key}>{[1,6,8,13].includes(i)&&<div className="studio-group">{i===1?tr("DEVELOP"):i===6?tr("QUALITY"):i===8?tr("PRODUCE"):tr("DELIVER")}</div>}<a href={'#/projects/'+id+'/'+key} className={tab===key?'active':''}><Icon size={16}/>{tr(title)}{key==='audit'&&p.issues.filter((x:Row)=>x.fix_status==='OPEN').length>0&&<span className="nav-counter">{p.issues.filter((x:Row)=>x.fix_status==='OPEN').length}</span>}</a></React.Fragment>)}</nav><div className="studio-content"><ViewTranslationToolbar/>
  {active&&<div className="job-banner"><Loader2 className={active.status==='running'?'spin':''} size={18}/><div><strong>{label(active.kind)}</strong><span>{tr(active.step)}</span><Progress value={active.progress}/></div><a className="text-link" href={'#/jobs/'+id}>{active.status==='waiting_user'?tr("Complete in Jobs"):tr("View job")}<ArrowRight size={14}/></a></div>}
  {tab==='overview'&&<><Section title={tr("Your story at a glance")} caption={tr("A deliberate path from inspiration to finished production")}><div className="duration-summary"><Stat label={tr("Word target")} value={p.profile.target_words.toLocaleString()} note={p.profile.word_range.join('–')+tr(' words')}/><Stat label={tr("Characters")} value={p.profile.characters.join('–')}/><Stat label={tr("Scenes")} value={p.profile.scenes.join('–')}/></div><div className="notice"><span className="empty-icon small-icon"><ArrowRight size={20}/></span><div><strong>{tr("Up next")}</strong><p>{p.next.checkpoint?tr(p.next.checkpoint):label(p.next.kind)}</p></div></div><div className="retention-map">{p.profile.retention_map.map((beat:Row)=><div key={tr(beat.label)}><span>{time(beat.seconds)}</span><i/><strong>{tr(beat.label)}</strong></div>)}</div></Section><Section title={tr("Duration settings")} caption={tr("Duration shapes the cast, plot complexity, scene plan and word target.")}><DurationEditor project={p}/></Section><Section title={tr("Inspiration & direction")}><p>{p.source?.summary||tr("An original story, developed from the channel identity.")}</p>{p.source&&<a className="text-link" href={'#/inbox/'+p.source_id}>{tr("Explore source")}<ArrowRight size={14}/></a>}</Section></>}
  {tab==='direction'&&<Section title={tr("A clear creative direction")} caption={tr("Keep the abstract appeal. Transform the rest.")} action={action('content_direction','Generate direction',true)}>{artifact('content_direction')?<ArtifactView item={p.artifacts.content_direction}/>:<Empty title={tr("Give this story its own direction")} description={tr("Combine the channel identity, source motifs and novelty memory before generating premises.")}/>}</Section>}
  {tab==='premises'&&<Premises project={p} run={run} active={!!active}/>}
  {tab==='bible'&&<Section title={tr("The ground truth of your story")} caption={tr("Characters, knowledge, resources and world rules stay consistent from here.")} action={action('story_bible','Create Story Bible',true)}>{artifact('story_bible')?<ArtifactView item={p.artifacts.story_bible}/>:<Empty title={tr("Build the world before the words")} description={tr("Select a premise, then generate the Story Bible.")}/>}</Section>}
  {tab==='outline'&&<><Section title={tr("The architecture of your story")} action={<div className="inline wrap">{action('outline','Generate')}{action('outline_audit','Audit')}{action('outline_rewrite','Targeted revision',true)}</div>}>{(artifact('outline_rewrite')||artifact('outline'))?<div className="outline-list">{(artifact('outline_rewrite')||artifact('outline')).scenes.map((s:Row)=><details key={s.scene_id}><summary><span className="scene-number">{s.scene_id}</span><strong><ViewText text={s.title||s.purpose}/></strong><span className="muted">{time(s.estimated_time)}</span><ChevronDown size={16}/></summary><Readable value={s}/></details>)}</div>:<Empty title={tr("Map every turn")} description={tr("Create a duration-aware outline from your selected premise and Story Bible.")}/>}</Section>{artifact('outline_audit')&&<Section title={tr("Outline audit")}><Readable value={artifact('outline_audit')}/></Section>}</>}
  {tab==='draft'&&<DraftEditor project={p} action={action('full_draft','Generate draft',true)}/>}
  {tab==='audit'&&<Audit project={p} action={action} onIssue={setIssue} run={run} active={!!active}/>}
  {tab==='versions'&&<Versions project={p}/>}
  {tab==='tts'&&<TTS project={p} run={run} active={!!active}/>}
  {tab==='visuals'&&<Visuals project={p} run={run} active={!!active}/>}
  {tab==='assets'&&<Assets project={p}/>}
  {tab==='timeline'&&<Timeline project={p} run={run} active={!!active}/>}
  {tab==='render'&&<Render project={p} run={run} active={!!active}/>}
  {tab==='publish'&&<Publish project={p}/>}
  </div></div>{issue&&<IssueDetail issue={issue} project={p} onClose={()=>setIssue(null)}/>}</ViewTranslationScope>
}

function ArtifactView({item}:{item:Row}){const {act}=useApp();return <><div className="provenance"><Badge tone={item.provider.startsWith('mock')?'amber':'blue'}>{item.provider}</Badge><span>{tr("Template ")}{item.template_version} · {new Date(item.created_at).toLocaleString()}</span><span title={item.output_hash}>{tr("SHA256 ")}{item.output_hash?.slice(0,10)}</span></div><JsonEditor value={item.content} onSave={content=>act(()=>api('/artifacts/'+item.id,'PATCH',{content}),'Artifact version saved')}/></>}
function DurationEditor({project:p}:{project:Row}){const {act}=useApp();const [form,setForm]=useState({target_minutes:p.target_minutes,wpm:p.wpm,duration_mode:p.duration_mode});return <form className="inline wrap" onSubmit={e=>{e.preventDefault();act(()=>api('/projects/'+p.id,'PATCH',form),'Duration updated')}}><Field label={tr("Mode")}><select disabled={p.locked} value={form.duration_mode} onChange={e=>setForm({...form,duration_mode:e.target.value,target_minutes:Number(e.target.value)||form.target_minutes})}>{['Auto','5','10','20','30','45','60','Custom'].map(v=><option key={v} value={v}>{tr(v)}</option>)}</select></Field><Field label={tr("Minutes")}><input type="number" min="1" max="240" disabled={p.locked} value={form.target_minutes} onChange={e=>setForm({...form,target_minutes:+e.target.value})}/></Field><Field label={tr("Words / minute")}><input type="number" min="80" max="240" disabled={p.locked} value={form.wpm} onChange={e=>setForm({...form,wpm:+e.target.value})}/></Field><Button type="submit" disabled={p.locked} title={p.locked?tr("Create a new draft version to change production settings"):''}><Save size={15}/>{tr("Save")}</Button>{form.duration_mode==='Auto'&&<p className="muted">{tr("Local recommendation: ")}{p.auto_duration.range.join('–')} {tr("minutes for a simple premise. Accept a value above or override it.")}</p>}</form>}
function Premises({project:p,run,active}:{project:Row,run:(kind:string,payload?:Row)=>void,active:boolean}){
  const {act}=useApp();const [count,setCount]=useState(p.workflow_settings.default_premise_count),[mini,setMini]=useState<Row|null>(null);
  return <><Section title={tr("Find the story only you would tell")} caption={tr("Diverse premises, scored against your audience, channel and target duration.")} action={<div className="inline"><select aria-label={tr("Premise count")} value={count} onChange={e=>setCount(+e.target.value)}>{[...new Set([5,10,20,30,50,p.workflow_settings.default_premise_count])].sort((a,b)=>a-b).map(v=><option value={v} key={v}>{v} {tr("premises")}</option>)}</select><Button primary disabled={active||!!p.selected_premise_id} title={p.selected_premise_id?tr("A premise is already selected"):''} onClick={()=>run('premise_generation',{count})}><Sparkles size={16}/>{tr("Generate")}</Button></div>}><div className="notice compact">{tr("All premise scores are heuristic. Similarity and repetition scores are risks: lower is better.")}</div>{p.premises.length?<><div className="inline between"><p className="muted">{tr("40% Core · 30% Adjacent · 20% Experimental · 10% Wildcard")}</p><Button disabled={active} onClick={()=>run('premise_mini_test')}><WandSparkles size={15}/>{tr("Mini-test top 3")}</Button></div><div className="premise-grid">{p.premises.map((pr:Row,i:number)=><article key={pr.id} className={'premise-card '+(p.selected_premise_id===pr.id?'chosen':'')}><div className="inline between"><Badge tone={pr.category==='Core'?'blue':pr.category==='Adjacent'?'green':'violet'}>{tr(pr.category)}</Badge><span className="muted">{String(i+1).padStart(2,'0')}</span></div><h3><ViewText text={pr.title}/></h3><p><ViewText text={pr.logline}/></p><div className="premise-scores">{['hook','originality','duration_fit','source_similarity'].map(key=><div key={key}><strong>{pr.scores[key]}</strong><span>{label(key)}</span></div>)}</div><details><summary>{tr("All scoring dimensions")}</summary><Readable value={pr.scores}/></details>{pr.warnings.map((w:Row,j:number)=><div className="notice error compact" key={j}>{w.scope}: <ViewText text={w.title}/> · {w.score}%</div>)}<div className="inline between"><Button small disabled={!Object.keys(pr.mini_test).length} title={!Object.keys(pr.mini_test).length?tr("Run the top-three mini-test first"):''} onClick={()=>setMini(pr)}>{tr("View mini-test")}</Button><Button small primary disabled={!!p.selected_premise_id||pr.warnings.some((w:Row)=>w.level==='BLOCK')} onClick={()=>act(()=>api('/projects/'+p.id+'/select-premise','POST',{premise_id:pr.id}),'Premise selected')}>{p.selected_premise_id===pr.id?<><Check size={14}/>{tr("Selected")}</>:<>{tr("Choose")}<ArrowRight size={14}/></>}</Button></div></article>)}</div></>:<Empty title={tr("One idea. Many possibilities.")} description={tr("Generate candidate premises from your content direction, then mini-test the strongest three.")}/>}</Section>{mini&&<Modal title={mini.title} onClose={()=>setMini(null)} wide><Readable value={mini.mini_test}/></Modal>}</>
}
function DraftEditor({project:p,action}:{project:Row,action:React.ReactNode}){const {act}=useApp();const [text,setText]=useState(p.draft),[dirty,setDirty]=useState(false);useEffect(()=>{if(!dirty)setText(p.draft)},[p.draft,dirty]);return <Section title={tr("Let the story unfold")} caption={tr("American English narration · changes create a new version and invalidate affected production items.")} action={action}><div className="editor-toolbar"><span>{text.trim()?text.trim().split(/\s+/).length:0} {tr("words · target ")}{p.profile.word_range.join('–')}</span><div className="inline"><CopyButton text={text}/><Button small disabled={!text} onClick={()=>downloadText('story.txt',text)}><Download size={14}/>{tr("Export TXT")}</Button><Button small primary disabled={!dirty||!text.trim()} onClick={async()=>{const result=await act(()=>api('/projects/'+p.id,'PATCH',{draft:text}),'New story version saved');if(result)setDirty(false)}}><Save size={14}/>{tr("Save version")}</Button></div></div>{p.locked&&<div className="notice compact"><LockKeyhole size={16}/>{tr("Editing this locked draft will create a new unlocked story version.")}</div>}<DraftTranslation text={text}/><textarea className="draft-editor" aria-label={tr("Story draft")} spellCheck value={text} onChange={e=>{setText(e.target.value);setDirty(true)}} placeholder={tr("Your full narration will appear here. Generate a draft from the approved Story Bible and revised outline, or paste your own.")}/></Section>}
function Audit({project:p,action,onIssue,run,active}:{project:Row,action:(kind:string,text:string,primary?:boolean)=>React.ReactNode,onIssue:(i:Row)=>void,run:(k:string,payload?:Row)=>void,active:boolean}){
  const [filter,setFilter]=useState('All');const issues=p.issues.filter((i:Row)=>i.scope==='story'&&i.cycle===p.audit_cycle);const shown=issues.filter((i:Row)=>filter==='All'||i.severity===filter||i.final_status===filter||i.chatgpt_verdict===filter);
  return <><div className="stats-grid audit-stats">{['CRITICAL','HIGH','MEDIUM','LOW'].map(severity=><Stat key={severity} label={label(severity)} value={issues.filter((i:Row)=>i.severity===severity&&i.fix_status==='OPEN').length} note="Open issues"/>)}</div><Section title={tr("Two perspectives. A stronger story.")} caption={tr("Audit cycle {p0} of 3 · Every issue requires concrete evidence.",{p0:p.audit_cycle+1})}><div className="audit-actions">{action('gemini_story_audit','1. Gemini audit')}{action('chatgpt_cross_review','2. ChatGPT cross-review')}{action('disagreement_resolver','3. Resolve disagreements')}{action('targeted_rewrite','4. Targeted rewrite')}<Button primary disabled={active} onClick={()=>run('final_verify_gemini',{auto_continue:true})}><ShieldCheck size={16}/>{tr("5. Dual final verify")}</Button></div><div className="filter-chips">{['All','CRITICAL','HIGH','MEDIUM','LOW','CONFIRMED','REJECTED','UNCERTAIN','NEWLY_DISCOVERED'].map(f=><button key={tr(f)} className={filter===f?'active':''} onClick={()=>setFilter(f)}>{label(f)}</button>)}</div>{issues.length?<div className="table-wrap"><table className="audit-table"><thead><tr><th>{tr("Issue / location")}</th><th>{tr("Severity")}</th><th>{tr("Gemini claim")}</th><th>{tr("ChatGPT")}</th><th>{tr("Resolution")}</th><th>{tr("Fix")}</th></tr></thead><tbody>{shown.map((i:Row)=><tr key={i.id}><td><button className="link-button" onClick={()=>onIssue(i)}>{i.issue_key}</button><small><ViewText text={i.location}/></small></td><td><Status value={i.severity}/></td><td><span className="clamp-two"><ViewText text={i.gemini_claim}/></span></td><td><Status value={i.chatgpt_verdict}/></td><td><Status value={i.final_status}/></td><td><Status value={i.fix_status}/></td></tr>)}</tbody></table></div>:<Empty title={p.artifacts.gemini_story_audit?tr("No issues reported in this audit"):tr("A fresh set of eyes on your story")} description={p.artifacts.gemini_story_audit?tr("Complete the independent cross-review and both final verifications before Story Lock."):tr("Run the Gemini audit to find evidence-based consistency, logic and narration issues.")}/>}</Section><div className="two-col">{['final_verify_gemini','final_verify_chatgpt'].map(k=><Section key={k} title={k.endsWith('gemini')?tr("Gemini final verification"):tr("ChatGPT final verification")}>{p.artifacts[k]?<><Status value={p.artifacts[k].content.passed?'READY':'BLOCKED'}/><p><ViewText text={p.artifacts[k].content.summary}/></p><small className="muted">{tr("Verified draft ")}{p.artifacts[k].content.verified_hash?.slice(0,12)}</small></>:<p className="muted">{tr("Awaiting an independent verification of the current draft.")}</p>}</Section>)}</div></>
}
function IssueDetail({issue:i,project:p,onClose}:{issue:Row,project:Row,onClose:()=>void}){const {act}=useApp();const [reason,setReason]=useState('');return <Modal title={i.issue_key+' · '+i.type} onClose={onClose} wide><div className="inline"><Status value={i.severity}/><Status value={i.final_status}/></div><h3>{tr("Evidence")}</h3><blockquote><ViewText text={i.evidence}/></blockquote><p className="muted">{tr("Location: ")}<ViewText text={i.location}/></p><div className="two-col"><div><h3>{tr("Gemini claim")}</h3><p><ViewText text={i.explanation}/></p></div><div><h3>{tr("ChatGPT cross-review")}</h3><p><ViewText text={i.challenge||tr("Pending")}/></p></div></div><h3>{tr("Story Bible references")}</h3><Readable value={i.bible_references}/><h3>{tr("Repair requirement")}</h3><p><ViewText text={i.repair}/></p><h3>{tr("Resolution")}</h3><p><ViewText text={i.resolution||tr("Not yet resolved")}/></p><Field label={tr("Human review reason")}><textarea rows={3} value={reason} onChange={e=>setReason(e.target.value)} placeholder={tr("Explain the evidence supporting your decision…")}/></Field><div className="modal-actions">{['CONFIRMED','REJECTED','WITHDRAWN'].map(status=><Button small disabled={reason.trim().length<5} key={status} onClick={async()=>{const r=await act(()=>api('/issues/'+i.id+'/resolve','POST',{status,reason}),'Issue resolved');if(r)onClose()}}>{label(status)}</Button>)}</div></Modal>}
function Versions({project:p}:{project:Row}){const {act}=useApp();const [selected,setSelected]=useState('');return <><StoryLockApproval project={p} onApprove={body=>act(()=>api('/projects/'+p.id+'/lock','POST',body),'Story locked')}/><Section title={tr("Every version, preserved")}><div className="version-list">{p.versions.map((v:Row)=><div key={v.id}><div className="inline between"><div><h3>{tr("Version ")}{v.version}.0</h3><p>{new Date(v.created_at).toLocaleString()} · {v.text_hash.slice(0,12)}</p></div><Status value={v.locked?'LOCKED':'DRAFT'}/><Button small onClick={()=>setSelected(selected===v.id?'':v.id)}>{tr("Compare / affected items")}</Button></div>{selected===v.id&&<><Readable value={v.affected}/><div className="two-col compare"><div><h3>{tr("Version ")}{v.version}</h3><pre><ViewText text={v.text}/></pre></div><div><h3>{tr("Current draft")}</h3><pre><ViewText text={p.draft}/></pre></div></div></>}</div>)}</div>{!p.versions.length&&<Empty title={tr("Your story history starts with the first draft")} description={tr("Every change is saved as a reproducible version.")}/>}</Section></>}
function TTS({project:p,run,active}:{project:Row,run:(k:string,payload?:Row)=>void,active:boolean}){const {act}=useApp();return <><MediaAutomation project={p} kind="tts" active={active} act={act}/><Section title={tr('Closing thanks')} caption={tr('A separate audio segment thanks viewers and gently invites likes and subscriptions. Existing narration stays attached.')}><Button disabled={!p.locked||active||!p.chunks.length||p.chunks.some((c:Row)=>c.voice_profile?.segment_role==='outro')} onClick={()=>act(()=>api('/projects/'+p.id+'/outro','POST'),'Closing narration added')}>{tr('Add closing narration')}</Button><p className="muted">{tr('Generate and attach the new closing WAV, then sync and render again.')}</p></Section><Section title={tr("A voice for every word")} caption={tr("Sentence-safe chunks with non-spoken context and a consistent channel narrator.")} action={<Button primary disabled={!p.locked||active} title={!p.locked?tr("Story Lock is required"):''} onClick={()=>run('chunk_tts')}><AudioLines size={16}/>{tr("Build semantic chunks")}</Button>}>{!p.locked&&<div className="notice compact">{tr("Approve Story Lock before producing audio.")}</div>}{p.chunks.length?<div className="chunk-list">{p.chunks.map((c:Row)=><article className="chunk-card" key={c.id}><div className="inline between"><div className="inline"><span className="scene-number">{String(c.number).padStart(3,'0')}</span><h3>{tr("tts_")}{String(c.number).padStart(3,'0')}{tr(".wav")}</h3></div><Status value={c.status}/></div><div className="chunk-meta"><span><Clock3 size={14}/>{c.real_duration?time(c.real_duration)+tr(" actual"):time(c.estimated_duration)+tr(" estimated")}</span><span>{c.word_count} {tr("words")}</span><span><ViewText text={c.reasons.join(' · ')}/></span></div><details><summary>{tr("Read narration & voice context")}</summary><p className="narration-text"><ViewText text={c.text}/></p><h4>{tr("Non-spoken context")}</h4><p><ViewText text={c.previous_context}/></p><Readable value={c.voice_profile}/><h4>Scene · Google AI Studio</h4><p style={{whiteSpace:'pre-wrap'}}><ViewText text={c.scene_context}/></p></details><div className="inline wrap"><CopyButton text={c.scene_context||''} caption="Scene · AI Studio"/><CopyButton text={c.text} caption={tr("Full text")}/><CopyButton text={pretty(c.voice_profile)} caption={tr("Voice profile")}/><CopyButton text={c.previous_context+'\nMood: '+c.mood+'\nNext: '+c.next_context} caption={tr("Sample context")}/><Button small onClick={()=>downloadText(`tts_${String(c.number).padStart(3,'0')}.txt`,c.text)}><Download size={14}/>{tr("TXT")}</Button><a className="button small" href="https://aistudio.google.com/generate-speech" target="_blank" rel="noreferrer">{tr("AI Studio")}<ExternalLink size={13}/></a><Button small disabled={active} onClick={()=>run('tts_context',{text:c.text,voice:c.voice_profile,context:c.previous_context,scene:c.scene_context,chunk_id:c.id})}>{tr("Queue in bridge")}</Button><a className="button small" href={'#/projects/'+p.id+'/assets'}><Upload size={14}/>{tr("Attach WAV")}</a></div>{c.asset_id&&<audio controls preload="none" src={'/api/assets/'+c.asset_id+'/file'}/>}</article>)}</div>:<Empty title={tr("Preserve the rhythm of your narration")} description={tr("The chunker prefers complete sentences, paragraphs and scene transitions around three minutes, with a four-minute hard limit.")}/>}</Section></>}
function Visuals({project:p,run,active}:{project:Row,run:(k:string,payload?:Row)=>void,active:boolean}){const {act}=useApp();return <><MediaAutomation project={p} kind="visuals" active={active} act={act}/><ThumbnailStudio project={p} act={act}/><Section title={tr("Direct the world of your story")} caption={tr("Every prompt stays tied to the locked story version and character continuity.")} ><VisualPlanOptions project={p} active={active} act={act} run={()=>run('visual_director')}/>{p.scenes.length?<div className="visual-grid">{p.scenes.map((s:Row)=><article className="visual-card" key={s.id}><div className="visual-preview">{s.asset_id&&p.assets.find((a:Row)=>a.id===s.asset_id)?.kind==='image'?<img src={'/api/assets/'+s.asset_id+'/file'} alt={tr("Scene ")+s.number}/>:<><MountainArt variant={p.channel.color}/><span className="visual-scene-label">{tr("SCENE ")}{String(s.number).padStart(3,'0')}</span></>}<Badge tone={s.visual_type==='VIDEO'?'amber':'blue'}>{label(s.visual_type)}</Badge></div><div className="visual-card-body"><div className="inline between"><h3>{s.scene_key}</h3><span className="muted">{tr("Words ")}{s.start_word}–{s.end_word}</span></div><p><ViewText text={s.prompt}/></p><details><summary>{tr("Continuity & negative prompt")}</summary><p><ViewText text={s.negative_prompt}/></p><Readable value={s.continuity}/></details><div className="inline wrap"><CopyButton text={s.prompt+'\nAvoid: '+s.negative_prompt} caption={tr("Prompt")}/><Button small disabled={active} onClick={()=>run(s.visual_type==='VIDEO'?'video_generation':'image_generation',{prompt:s.prompt,negative_prompt:s.negative_prompt,scene_id:s.id})}>{tr("Queue in bridge")}</Button><a className="button small" href={s.visual_type==='VIDEO'?'https://flow.google.com/':'https://gemini.google.com/app'} target="_blank" rel="noreferrer"><ExternalLink size={13}/>{tr("Open ")}{s.visual_type==='VIDEO'?tr("Flow"):tr("Gemini")}</a></div></div></article>)}</div>:<Empty title={tr("Make every scene visible")} description={tr("Generate a duration-aware scene plan after Story Lock, then use Gemini Images or Google Flow and attach the results.")}/>}</Section></>}
function Assets({project:p}:{project:Row}){
  const {act}=useApp();const selection=usePageSelection(p.assets);const [validation,setValidation]=useState<Row|null>(null),[mapping,setMapping]=useState<Row|null>(null),[target,setTarget]=useState(''),[fallback,setFallback]=useState(false);
  async function upload(files:FileList|File[]|null){if(!files?.length)return;const body=new FormData();Array.from(files).forEach(f=>body.append('files',f));await act(()=>api('/projects/'+p.id+'/assets','POST',body),'Assets imported and mapped');}
  return <><Section title={tr("Everything your story needs")} caption={tr("Map any filename to its audio segment or scene. Each scene accepts an image or video; standard names only help automatic mapping.")} action={<Button onClick={()=>act(async()=>{const r=await api('/projects/'+p.id+'/validate');setValidation(r);return r},'Validation complete')}><ListChecks size={16}/>{tr("Validate assets")}</Button>}><label className="dropzone" onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();upload(e.dataTransfer.files)}}><Upload size={27}/><strong>{tr("Drop your audio, images and video here")}</strong><span>{tr("or click to browse · bulk import · duplicate detection")}</span><input type="file" multiple accept=".wav,.mp3,.m4a,.flac,.ogg,.png,.jpg,.jpeg,.webp,.mp4,.mov,.webm" onChange={e=>{upload(e.target.files);e.target.value=''}}/></label>{validation&&<div className={'notice '+(validation.valid?'success':'error')}><div><strong>{validation.valid?tr("All required assets are available"):tr("Some assets need attention")}</strong><p>{tr("Narration ")}{validation.narration.join('/')} {tr("· Visuals ")}{validation.visuals.join('/')}</p>{validation.missing.map((m:string)=><p key={m}><ViewText text={m}/></p>)}{validation.warnings.map((w:string)=><p key={w}><ViewText text={w}/></p>)}</div></div>}<AssetSelection project={p} selection={selection} act={act} onDeleted={()=>setValidation(null)}/><div className="asset-grid">{p.assets.map((a:Row)=><article className="asset-card" key={a.id}><div className="asset-preview">{a.kind==='image'?<img loading="lazy" src={'/api/assets/'+a.id+'/file'} alt={a.name}/>:a.kind==='video'?<video controls preload="metadata" src={'/api/assets/'+a.id+'/file'}/>:<><AudioLines size={32}/><audio controls preload="none" src={'/api/assets/'+a.id+'/file'}/></>}</div><div className="asset-info"><label className="check-field"><input type="checkbox" aria-label={tr("Select asset")+" "+a.name} checked={selection.ids.includes(a.id)} onChange={()=>selection.toggle(a.id)}/><span>{tr("Select asset")}</span></label><strong title={a.name}>{a.name}</strong><small>{[...p.chunks.filter((c:Row)=>c.asset_id===a.id).map((c:Row)=>"TTS "+c.number),...p.scenes.filter((s:Row)=>s.asset_id===a.id||s.fallback_asset_id===a.id).map((s:Row)=>tr("Scene ")+s.number+(s.fallback_asset_id===a.id?" ("+tr("Fallback")+")":""))].join(" · ")||tr("Not assigned")}</small><span>{label(a.kind)} · {(a.size/1024/1024).toFixed(2)} {tr("MB")}{a.duration?' · '+time(a.duration):''}</span><div className="inline between"><small title={a.sha256}>{tr("SHA ")}{a.sha256.slice(0,8)}</small><Button small onClick={()=>{setMapping(a);setTarget('');setFallback(false)}}>{tr("Map asset")}<ChevronRight size={13}/></Button></div></div></article>)}</div></Section>{mapping&&<Modal title={tr("Map ")+mapping.name} onClose={()=>setMapping(null)}><Field label={tr("Production target")}><select value={target} onChange={e=>setTarget(e.target.value)}><option value="">{tr("Choose a target")}</option>{(mapping.kind==='audio'?p.chunks:p.scenes).map((t:Row)=><option key={t.id} value={t.id}>{mapping.kind==='audio'?tr("TTS chunk"):tr("Visual scene")} {t.number}</option>)}</select></Field>{mapping.kind==='image'&&<label className="check-field"><input type="checkbox" checked={fallback} onChange={e=>setFallback(e.target.checked)}/>{tr("Use as fallback for a video scene")}</label>}{['music','ambient','sfx'].includes(mapping.kind)&&<p className="muted">{tr("Music and ambient tracks are included in the audio mix automatically. SFX offset and volume are editable in the metadata below.")}</p>}<JsonEditor value={{offset:mapping.metadata_json.offset||0,volume_db:mapping.metadata_json.volume_db||-18}} onSave={v=>act(()=>api('/assets/'+mapping.id,'PATCH',v),'Audio placement saved')}/><div className="modal-actions"><Button onClick={()=>setMapping(null)}>{tr("Cancel")}</Button><Button primary disabled={!target} onClick={async()=>{const r=await act(()=>api('/assets/'+mapping.id,'PATCH',{target_id:target,target_type:mapping.kind==='audio'?'tts':'scene',fallback}),'Asset mapped');if(r){setMapping(null);setValidation(null)}}}>{tr("Save mapping")}</Button></div></Modal>}</>
}
function Timeline({project:p,run,active}:{project:Row,run:(k:string)=>void,active:boolean}){const scenes=p.render_timeline?.scenes?.map((t:Row)=>({...p.scenes.find((s:Row)=>s.id===t.id),...t,scene_key:t.ending_thumbnail?tr('Ending thumbnail'):p.scenes.find((s:Row)=>s.id===t.id)?.scene_key,visual_type:t.media_kind==='video'?'VIDEO':'IMAGE',status:t.ending_thumbnail?'ATTACHED':p.scenes.find((s:Row)=>s.id===t.id)?.status}))||p.scenes;const total=p.chunks.reduce((sum:number,c:Row)=>sum+(c.real_duration||0),0);return <Section title={tr("Timing that follows the voice")} caption={tr("Scene and subtitle positions use real audio durations from ffprobe.")} action={<Button primary disabled={!p.locked||active} onClick={()=>run('sync')}><RefreshCw size={16}/>{tr("Sync to real audio")}</Button>}>{p.render_timeline?.error&&<p role="alert" className="error-text">{tr(p.render_timeline.error)}</p>}<div className="duration-summary"><Stat label={tr("Real narration")} value={time(total)}/><Stat label={tr("Audio chunks")} value={p.chunks.length}/><Stat label={tr("Visual coverage")} value={time(scenes.reduce((sum:number,s:Row)=>sum+s.duration,0))}/></div><div className="timeline-track"><span>{tr("NARRATION")}</span><div>{p.chunks.map((c:Row)=><div key={c.id} style={{flex:c.real_duration||1}} title={tr("Chunk ")+c.number+' · '+time(c.real_duration)}>{c.number}</div>)}</div></div><div className="timeline-track visuals"><span>{tr("VISUALS")}</span><div>{scenes.map((s:Row)=><div key={s.id} style={{flex:s.duration||1}} title={s.scene_key+' · '+time(s.duration)}>{s.number}</div>)}</div></div><div className="notice compact">{tr("Subtitles use sentence-weighted alignment inside each audio chunk. Review precise word timing before publishing.")}</div><div className="table-wrap"><table><thead><tr><th>{tr("Scene")}</th><th>{tr("Offset")}</th><th>{tr("Duration")}</th><th>{tr("Visual")}</th><th>{tr("Status")}</th></tr></thead><tbody>{scenes.map((s:Row)=><tr key={s.id}><td>{s.scene_key}</td><td>{time(s.offset)}</td><td>{s.duration.toFixed(2)}{tr("s")}</td><td>{label(s.visual_type)}</td><td><Status value={s.status}/></td></tr>)}</tbody></table></div>{total>0&&<div className="inline"><a className="button" href={'/api/projects/'+p.id+'/download/captions.srt'}><Download size={15}/>{tr("Captions SRT")}</a><a className="button" href={'/api/projects/'+p.id+'/download/captions.vtt'}>{tr("Captions VTT")}</a></div>}</Section>}
function Render({project:p,run,active}:{project:Row,run:(k:string)=>void,active:boolean}){const [optionsBusy,setOptionsBusy]=useState(false);const report=p.artifacts.render_report?.content;const {act}=useApp();const {data:validation}=useData('/projects/'+p.id+'/validate',0,2500);const lastRender=p.jobs.find((j:Row)=>j.kind==='render');return <><Section title={tr("Bring it all together")} caption={tr("Local FFmpeg · H.264 video · AAC audio · image motion · transitions · narration ducking")} action={<div className="inline"><Button onClick={()=>act(async()=>{const result=await api('/projects/'+p.id+'/validate');return result},'Assets validated')}><ListChecks size={16}/>{tr("Preflight")}</Button><Button primary disabled={!p.locked||active||optionsBusy} onClick={()=>run('render')}><Clapperboard size={16}/>{tr(report?"Render again":"Render first cut")}</Button></div>}><RenderOptions project={p} active={active} act={act} onBusy={setOptionsBusy}/>{validation&&<ProductionValidation value={validation} projectId={p.id}/>}
    {lastRender?.status==='failed'&&<p className="error-text" role="alert">{tr("Last render failed")}: {tr(lastRender.error)}</p>}
    {report&&p.artifacts.render_report.story_version!==p.story_version&&<p className="notice compact">{tr("This preview is from the previous render. Render again to apply the latest changes.")}</p>}<div className="notice compact">{tr("Subtitle timing is estimated within each audio segment. Review the final video before publishing.")}</div><div className="render-preview">{report?.file&&report.story_version===p.story_version?<video key={p.artifacts.render_report.id} controls preload="metadata" src={'/api/projects/'+p.id+'/download/final_video.mp4?revision='+p.artifacts.render_report.id}/>:<><Clapperboard size={44}/><h3>{tr("Your next story, on screen")}</h3><p>{tr("Attach assets, sync the timeline, then render your first cut.")}</p></>}</div><div className="notice compact">{tr("Videos keep their original duration and starting position. Only image scenes adjust to narration; the ending thumbnail fills any remaining audio.")}</div></Section>{report&&<Section title={tr("Final technical QA")} caption={tr("A technical pass still requires your final viewing approval.")} action={<Status value={report.status}/>}><div className="qa-checks">{Object.entries(report.checks).map(([key,value])=><div className={value?'pass':'fail'} key={key}>{value?<CheckCircle2 size={19}/>:<X size={19}/>}<span><ViewText text={label(key)}/></span><strong>{value?tr("Pass"):tr("Failed")}</strong></div>)}</div>{report.warnings.map((w:string)=><p className="error-text" key={w}><ViewText text={w}/></p>)}<div className="inline wrap">{['final_video.mp4','final_audio.wav','captions.srt','captions.vtt','timeline.csv','render_report.json'].map(name=><a className="button small" href={'/api/projects/'+p.id+'/download/'+name} key={name}><Download size={14}/>{name}</a>)}</div><label className="check-field"><input type="checkbox" checked={!!p.publish.final_reviewed} onChange={e=>act(()=>api('/projects/'+p.id,'PATCH',{publish:{...p.publish,final_reviewed:e.target.checked}}),'Final review saved')}/>{tr("I have watched the final video and reviewed narration, continuity, pacing and captions.")}</label></Section>}</>}
function Publish({project:p}:{project:Row}){const {act}=useApp();const [form,setForm]=useState({...p.publish,title:p.publish.title||p.title});const set=(key:string,value:any)=>setForm({...form,[key]:value});return <><YouTubeHandoff project={p} form={form} onApply={fields=>setForm((current:Row)=>({...current,...fields}))} act={act}/><Section title={tr("Ready for its audience")} caption={tr("Keep publishing metadata and analytics attached to the story. Upload is manual.")}><form onSubmit={e=>{e.preventDefault();act(()=>api('/projects/'+p.id,'PATCH',{publish:form}),'Publishing metadata saved')}}><Field label={tr("YouTube title")}><input value={form.title||''} onChange={e=>set('title',e.target.value)}/></Field><Field label={tr("Description")}><textarea rows={5} value={form.description||''} onChange={e=>set('description',e.target.value)}/></Field><Field label={tr("Thumbnail concept")}><textarea rows={3} value={form.thumbnail_concept||''} onChange={e=>set('thumbnail_concept',e.target.value)}/></Field><div className="form-grid"><Field label={tr("YouTube URL")}><input type="url" value={form.url||''} onChange={e=>set('url',e.target.value)} placeholder={tr("https://youtube.com/watch?v=…")}/></Field><Field label={tr("Publish date")}><input type="date" value={form.date||''} onChange={e=>set('date',e.target.value)}/></Field><Field label={tr("Tags / notes")}><input value={form.tags||''} onChange={e=>set('tags',e.target.value)}/></Field><Field label={tr("Final duration (seconds)")}><input type="number" min="0" value={form.final_duration||''} onChange={e=>set('final_duration',+e.target.value)}/></Field></div><Button primary type="submit"><Save size={16}/>{tr("Save metadata")}</Button></form></Section><Section title={tr("Take your project anywhere")}><div className="export-options"><a href={'/api/projects/'+p.id+'/export'}><Archive size={24}/><strong>{tr("Project archive")}</strong><span>{tr("Metadata, story, Bible, audits and prompts")}</span><Download size={17}/></a><a href={'/api/projects/'+p.id+'/export?media=true'}><Folder size={24}/><strong>{tr("Full portable project")}</strong><span>{tr("Include original media and asset map")}</span><Download size={17}/></a><CapCutExport key={p.id} projectId={p.id}/></div></Section></>}

function Jobs({version,returnProjectId}:{version:number,returnProjectId?:string}){
  const [page,setPage]=useState(0);const {data,error}=useData('/jobs?offset='+page*50,version,2000);const selection=usePageSelection(data?.items);const {act,refresh}=useApp();const [selected,setSelected]=useState<string|null>(null),[result,setResult]=useState('');
  const job=data?.items.find((j:Row)=>j.id===selected);
  const projectIds=[...new Set<string>((data?.items||[]).map((j:Row)=>j.project_id).filter(Boolean))];
  const overviewId=returnProjectId||(projectIds.length===1?projectIds[0]:null);
  const overviewHref=overviewId?'#/projects/'+overviewId+'/overview':'#/channels';
  return <><PageHead eyebrow={tr("THE WORK BEHIND THE STORIES")} title={tr("Activity & jobs")} description={tr("Every step is saved. Resume interrupted work, review logs, or continue manually.")}/><BulkToolbar trailing={<a className="button small overview-return" href={overviewHref}><ArrowLeft size={15} aria-hidden="true"/>{tr("Back to overview")}</a>} kind="jobs" selection={selection} count={data?.items.length||0} onDeleted={()=>{setSelected(null);setPage(0);refresh()}}/><Section>{!data?<Loading error={error}/>:data.items.length?<div className="jobs-list">{data.items.map((j:Row)=><article className="job-row" key={j.id}><input type="checkbox" className="job-select" aria-label={tr("Select ")+label(j.kind)+" · "+j.id} checked={selection.ids.includes(j.id)} onChange={()=>selection.toggle(j.id)}/><span className="job-icon">{j.status==='completed'?<CheckCircle2 size={21}/>:j.status==='running'?<Loader2 className="spin" size={21}/>:<ListChecks size={21}/>}</span><div className="job-info"><strong>{label(j.kind)}</strong><p>{tr(j.step)}</p><span className="muted">{j.provider} · {new Date(j.created_at).toLocaleString()}</span>{j.error&&<p className="error-text">{j.error}</p>}<Progress value={j.progress}/></div><Status value={j.status}/><div className="inline wrap">{j.kind==='tts_context'&&j.status==='waiting_user'&&<CompleteResourcesButton job={j} onCompleted={()=>{setSelected(null);refresh()}}/>}<Button small onClick={()=>{setSelected(j.id);setResult('')}}>{j.status==='waiting_user'?tr("Continue manually"):tr("Details")}</Button>{['failed','waiting_user','cancelled'].includes(j.status)&&<Button small onClick={()=>act(()=>api('/jobs/'+j.id+'/retry','POST'),'Job resumed')}><RefreshCw size={13}/>{tr("Retry")}</Button>}{!['completed','cancelled'].includes(j.status)&&<Button small onClick={()=>act(()=>api('/jobs/'+j.id+'/cancel','POST'),'Job cancelled')}>{tr("Cancel")}</Button>}<DeletionButton kind="jobs" ids={[j.id]} title={label(j.kind)} onDeleted={()=>{if(selected===j.id)setSelected(null);refresh()}}/></div></article>)}</div>:<Empty title={tr("Ready when inspiration strikes")} description={tr("Workflow jobs, browser tasks and render progress appear here.")}/>}</Section><ListPagination page={page} total={data?.total||0} onChange={next=>{selection.clear();setPage(next)}}/>{job&&<Modal title={label(job.kind)} onClose={()=>setSelected(null)} wide><div className="inline"><Status value={job.status}/><span className="muted">{job.provider}</span></div>{job.status==='waiting_user'&&<><div className="notice compact">{tr("Use the paired Browser Bridge, or copy this prompt into the provider and paste its JSON result below.")}</div><div className="inline"><CopyButton text={job.prompt} caption={tr("Copy full prompt")}/>{job.result.url&&<a className="button" href={job.result.url} target="_blank" rel="noreferrer">{tr("Open provider")}<ExternalLink size={14}/></a>}</div><details><summary>{tr("Prompt and input context")}</summary><pre>{job.prompt}</pre></details><Field label={tr("Paste provider result (JSON)")}><textarea className="code-editor" value={result} onChange={e=>setResult(e.target.value)} placeholder={'{ "…": "…" }'}/></Field><Button primary disabled={!result.trim()} onClick={async()=>{const r=await act(()=>api('/jobs/'+job.id+'/result','POST',{result}),'Result validated and saved');if(r)setSelected(null)}}><Check size={16}/>{tr("Capture result")}</Button></>}<h3>{tr("Job log")}</h3><pre>{job.logs.map((l:Row)=>l.time+' '+l.message).join('\n')||job.step}</pre>{job.error&&<p className="error-text">{job.error}</p>}{job.status==='completed'&&<JsonEditor value={job.result} readOnly/>}</Modal>}</>
}

function Calendar({version}:{version:number}){
  const {data,error}=useData('/calendar',version);const {data:channels}=useData('/channels');const {data:projects}=useData('/projects');const {act}=useApp();const [modal,setModal]=useState(false),[form,setForm]=useState({channel_id:'',project_id:'',title:'',target_date:new Date().toISOString().slice(0,10),category:'Core',duration:10});
  const set=(k:string,v:any)=>setForm({...form,[k]:v});
  return <><PageHead eyebrow={tr("MAKE ROOM FOR WHAT COMES NEXT")} title={tr("Content calendar")} description={tr("A balanced mix of familiar favorites and new possibilities.")} action={<Button primary onClick={()=>setModal(true)}><Plus size={16}/>{tr("Plan a video")}</Button>}/>{data?.warning&&<div className="notice">{data.warning}</div>}<div className="stats-grid">{['Core','Adjacent','Experimental','Wildcard'].map((c,i)=><Stat key={c} label={c} value={data?.mix[c]||0} note={tr('Suggested mix: {percent}%',{percent:[40,30,20,10][i]})}/>)}</div><Section title={tr("On the horizon")}>{!data?<Loading error={error}/>:data.items.length?<div className="calendar-list">{data.items.map((entry:Row)=><div className="calendar-row" key={entry.id}><div className="calendar-date"><small>{new Date(entry.target_date+'T12:00:00').toLocaleDateString('en-US',{month:'short'})}</small><strong>{entry.target_date.slice(-2)}</strong></div><div><h3>{entry.title}</h3><p>{channels?.items.find((c:Row)=>c.id===entry.channel_id)?.name} · {entry.duration} {tr("min")}</p></div><Badge tone="blue">{tr(entry.category)}</Badge><Status value={entry.status}/><Button small onClick={()=>act(()=>api('/calendar/'+entry.id,'DELETE'),'Plan removed')}><Trash2 size={14}/>{tr("Remove")}</Button></div>)}</div>:<Empty title={tr("The next chapter is unwritten")} description={tr("Plan a video or create a hypothesis test plan from a discovery channel.")}/>}</Section>{modal&&<Modal title={tr("Plan a video")} onClose={()=>setModal(false)}><form onSubmit={async e=>{e.preventDefault();const r=await act(()=>api('/calendar','POST',{...form,project_id:form.project_id||null}),'Video planned');if(r)setModal(false)}}><Field label={tr("Channel")}><select required value={form.channel_id} onChange={e=>set('channel_id',e.target.value)}><option value="">{tr("Choose channel")}</option>{channels?.items.map((c:Row)=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Field label={tr("Video title / premise")}><input required value={form.title} onChange={e=>set('title',e.target.value)}/></Field><Field label={tr("Link a project (optional)")}><select value={form.project_id} onChange={e=>set('project_id',e.target.value)}><option value="">{tr("No project yet")}</option>{projects?.items.filter((p:Row)=>p.channel_id===form.channel_id).map((p:Row)=><option key={p.id} value={p.id}>{p.title}</option>)}</select></Field><div className="form-grid"><Field label={tr("Target date")}><input required type="date" value={form.target_date} onChange={e=>set('target_date',e.target.value)}/></Field><Field label={tr("Duration (minutes)")}><input type="number" min="1" max="240" value={form.duration} onChange={e=>set('duration',+e.target.value)}/></Field></div><Field label={tr("Content mix")}><select value={form.category} onChange={e=>set('category',e.target.value)}>{['Core','Adjacent','Experimental','Wildcard'].map(c=><option key={c} value={c}>{tr(c)}</option>)}</select></Field><div className="modal-actions"><Button onClick={()=>setModal(false)} type="button">{tr("Cancel")}</Button><Button primary type="submit">{tr("Add to calendar")}</Button></div></form></Modal>}</>
}
function Analytics({version}:{version:number}){
  const {data,error}=useData('/analytics',version);const {data:projects}=useData('/projects');const {act}=useApp();const [modal,setModal]=useState(false),[form,setForm]=useState<Row>({project_id:'',date:new Date().toISOString().slice(0,10),views:0,impressions:0,ctr:0,average_view_duration:0,average_percentage_viewed:0,subscribers_gained:0,returning_viewers:0,likes:0,comments:0});
  const l=data?.learning;
  return <><PageHead eyebrow={tr("LISTEN TO YOUR AUDIENCE")} title={tr("A little wiser with every story")} description={tr("Record real results, look for patterns, and test what to change next.")} action={<Button primary onClick={()=>setModal(true)}><Plus size={16}/>{tr("Add analytics snapshot")}</Button>}/><div className="stats-grid"><Stat label={tr("Observed videos")} value={l?.sample_size||0} note="Unique projects, latest snapshot"/><Stat label={tr("Total views")} value={(l?.total_views||0).toLocaleString()}/><Stat label={tr("Average CTR")} value={(l?.average_ctr||0)+'%'}/><Stat label={tr("Evidence level")} value={l?.confidence||'Insufficient'}/></div><Section title={tr("Patterns, with perspective")} caption={tr("Observational comparisons never declare a winning niche automatically.")}>{l?.patterns.length?<div className="analytics-bars">{l.patterns.map((p:Row)=><div key={tr(p.category)}><div className="inline between"><strong>{tr(p.category)}</strong><span>{p.sample_size} {tr("videos · ")}{p.average_percentage_viewed}{tr("% viewed")}</span></div><Progress value={p.average_percentage_viewed}/></div>)}</div>:<Empty title={tr("Real learning starts with real data")} description={tr("Enter a snapshot from YouTube Studio. Sample size and evidence level will always be shown.")}/>}{l?.recommendations.map((r:string)=><div className="notice compact" key={r}><GitBranch size={18}/>{r}</div>)}</Section><Section title={tr("Performance snapshots")}>{!data?<Loading error={error}/>:<div className="table-wrap"><table><thead><tr><th>{tr("Story / snapshot date")}</th><th>{tr("Views")}</th><th>{tr("Impressions")}</th><th>{tr("CTR")}</th><th>{tr("Avg. view")}</th><th>{tr("% viewed")}</th><th>{tr("Subscribers")}</th></tr></thead><tbody>{data.items.map((r:Row)=><tr key={r.id}><td><strong>{r.project_title}</strong><small>{r.date}</small></td><td>{r.views.toLocaleString()}</td><td>{r.impressions.toLocaleString()}</td><td>{r.ctr}%</td><td>{time(r.average_view_duration)}</td><td>{r.average_percentage_viewed}%</td><td>{r.subscribers_gained}</td></tr>)}</tbody></table></div>}</Section>{modal&&<Modal title={tr("Add an observed snapshot")} onClose={()=>setModal(false)} wide><form onSubmit={async e=>{e.preventDefault();const r=await act(()=>api('/analytics','POST',form),'Analytics snapshot saved');if(r)setModal(false)}}><div className="form-grid"><Field label={tr("Project")}><select required value={form.project_id} onChange={e=>setForm({...form,project_id:e.target.value})}><option value="">{tr("Choose project")}</option>{projects?.items.map((p:Row)=><option value={p.id} key={p.id}>{p.title}</option>)}</select></Field><Field label={tr("Snapshot date")}><input type="date" required value={form.date} onChange={e=>setForm({...form,date:e.target.value})}/></Field>{Object.keys(form).filter(k=>!['project_id','date'].includes(k)).map(k=><Field key={k} label={label(k)+(k==='average_view_duration'?' (seconds)':'')}><input type="number" step={['ctr','average_percentage_viewed','average_view_duration'].includes(k)?'.01':'1'} min={k==='subscribers_gained'?undefined:0} max={['ctr','average_percentage_viewed'].includes(k)?100:undefined} value={form[k]} onChange={e=>setForm({...form,[k]:+e.target.value})}/></Field>)}</div><div className="modal-actions"><Button type="button" onClick={()=>setModal(false)}>{tr("Cancel")}</Button><Button primary type="submit">{tr("Save snapshot")}</Button></div></form></Modal>}</>
}
function Novelty({version}:{version:number}){const {data,error}=useData('/novelty',version);const {refresh}=useApp();return <><PageHead eyebrow={tr("ROOM FOR SOMETHING NEW")} title={tr("Novelty memory")} description={tr("Keep your worlds distinct, within a channel and across the workspace.")}/><div className="notice compact"><GitBranch size={18}/>{data?.method||tr("Structured motifs and local similarity hashes.")}</div><Section title={tr("Stories your workspace remembers")}>{!data?<Loading error={error}/>:data.items.length?data.items.map((n:Row)=><div className="novelty-entry" key={n.id}><details className="novelty-row"><summary><strong>{n.title}</strong><span className="muted">{n.text_hash.slice(0,12)}</span></summary><Readable value={n.signature}/><a href={'#/projects/'+n.project_id} className="text-link">{tr("Open story")}<ArrowRight size={14}/></a></details><DeletionButton kind="novelty" ids={[n.id]} title={n.title} onDeleted={refresh}/></div>):<Empty title={tr("Your creative memory starts here")} description={tr("Locked stories add their protagonists, settings, twists and beat signatures to the duplicate guard.")}/>}</Section></>}

function Settings({version,initialTab}:{version:number,initialTab?:string}){
  const {data:settings,error}=useData('/settings',version);const {data:health}=useData('/health',version);const {data:prompts}=useData('/prompts',version);const {act}=useApp();const [tab,setTab]=useState(initialTab==='bridge'?'Browser Bridge':'General'),[form,setForm]=useState<Row>({}),[pair,setPair]=useState(''),[promptName,setPromptName]=useState('story_dna'),[promptText,setPromptText]=useState(''),[dataPath,setDataPath]=useState('');
  useEffect(()=>{if(settings){setForm(settings);setDataPath(settings.data_root)}},[settings]);
  useEffect(()=>{api('/prompts/'+promptName).then(p=>setPromptText(p.text)).catch(()=>{})},[promptName]);
  if(!settings)return <Loading error={error}/>;
  const set=(k:string,v:any)=>setForm(prev=>({...prev,[k]:v}));
  return <><PageHead eyebrow={tr("MAKE THE STUDIO YOURS")} title={tr("Settings")} description={tr("Local storage, production defaults and your browser-based creative tools.")}/><div className="tabs page-tabs">{['General','Production','Browser Bridge','Prompt templates','Backup & storage'].map(t=><button key={tr(t)} className={tab===t?'active':''} onClick={()=>setTab(t)}>{tr(t)}</button>)}</div>
  {tab==='General'&&<UpdateSettings/>}{tab==='General'&&<section className="panel"><LanguagePicker/><p className="muted">{tr('Changes labels only. Story language, prompts and production settings stay the same.')}</p></section>}{(tab==='General'||tab==='Production')&&<Section title={tab==='General'?tr("Workspace defaults"):tr("Your production toolkit")}><form onSubmit={e=>{e.preventDefault();act(()=>api('/settings','PATCH',form),'Settings saved')}}>{tab==='General'?<><Field label={tr("AI provider mode")}><select value={form.provider_mode} onChange={e=>set('provider_mode',e.target.value)}><option value="mock">{tr("Mock · offline fixtures for workflow testing")}</option><option value="browser">{tr("Browser Bridge · your signed-in web providers")}</option></select></Field><div className="notice compact">{tr("Mock mode produces synthetic story fixtures and does not generate production media. Browser subscriptions are separate from API access.")}</div><div className="form-grid">{[['default_wpm','Default narration WPM',80,240],['default_duration','Default duration (minutes)',1,240],['default_premise_count','Default premise count',1,50],['max_audit_cycles','Maximum audit cycles',1,3]].map(([key,caption,min,max]:any)=><Field label={caption} key={key}><input type="number" min={min} max={max} value={form[key]} onChange={e=>set(key,+e.target.value)}/></Field>)}</div><Field label={tr("Workflow mode")} hint={tr("Manual runs one step. Assisted also pauses after outline and draft. Auto runs to your human checkpoints.")}><select value={form.pipeline_mode} onChange={e=>set('pipeline_mode',e.target.value)}><option value="manual">{tr("Manual")}</option><option value="assisted">{tr("Assisted")}</option><option value="auto">{tr("Auto with human checkpoints")}</option></select></Field><details><summary>{tr("Advanced checkpoint settings")}</summary><label className="check-field"><input type="checkbox" checked={form.auto_select_premise} onChange={e=>set('auto_select_premise',e.target.checked)}/>{tr("Auto-select the highest qualified mini-tested premise")}</label><label className="check-field"><input type="checkbox" checked={form.auto_lock} onChange={e=>set('auto_lock',e.target.checked)}/>{tr("Auto-lock after both current-version verification gates pass")}</label><p className="muted">{tr("Both options are off by default. Final video review remains manual.")}</p></details></>:<><div className="notice compact"><Status value={health?.ffmpeg&&health?.ffprobe?'READY':'BLOCKED'}/><span>{health?.ffmpeg?tr("FFmpeg and ffprobe auto-detected."):tr("Set the paths below or place ffmpeg.exe and ffprobe.exe in the app tools folder.")}</span></div><Field label={tr("Render acceleration")}><select value={form.render_encoder||'auto'} onChange={e=>set('render_encoder',e.target.value)}><option value="auto">{tr("Automatic GPU · CPU fallback")}</option><option value="cpu">{tr("CPU only")}</option></select></Field><p className="muted">{tr("H.264: target 5 Mbps with GPU, quality-based VBR with CPU; AAC 160 kbps. Unchanged scenes are reused when rendering again.")}</p><Field label={tr("FFmpeg executable (empty = auto-detect)")}><input value={form.ffmpeg_path} placeholder={health?.ffmpeg||tr("Path to ffmpeg.exe")} onChange={e=>set('ffmpeg_path',e.target.value)}/></Field><Field label={tr("ffprobe executable (empty = auto-detect)")}><input value={form.ffprobe_path} placeholder={health?.ffprobe||tr("Path to ffprobe.exe")} onChange={e=>set('ffprobe_path',e.target.value)}/></Field><div className="form-grid">{[['render_width','Video width',320,3840],['render_height','Video height',180,2160],['render_fps','Frames per second',12,60],['visual_video_ratio','Video scene ratio',0,1],['transition_seconds','Crossfade (seconds)',0,1.5],['silence_threshold','Silence QA threshold (seconds)',.5,60],['narration_db','Narration (dB)',-20,12],['music_db','Music (dB)',-60,0],['ambient_db','Ambient (dB)',-60,0]].map(([key,caption,min,max]:any)=><Field label={caption} key={key}><input type="number" step={['visual_video_ratio','transition_seconds','silence_threshold'].includes(key)?'.05':'1'} min={min} max={max} value={form[key]} onChange={e=>set(key,+e.target.value)}/></Field>)}<Field label={tr("Narrator voice name")}><input value={form.voice_name} onChange={e=>set('voice_name',e.target.value)}/></Field></div><label className="check-field"><input type="checkbox" checked={form.allow_visual_fallback} onChange={e=>set('allow_visual_fallback',e.target.checked)}/>{tr("Allow labeled placeholder visuals when images are missing (QA requires review)")}</label></>}<div className="form-footer"><Button primary type="submit"><Save size={16}/>{tr("Save settings")}</Button></div></form></Section>}
  {tab==='Browser Bridge'&&<><Section title={tr("Your browser. Your accounts.")} caption={tr("Chrome / Edge extension · Manifest V3 · no API keys required")}><div className="provider-grid">{[['ChatGPT','Story creation & cross-review','https://chatgpt.com/'],['Gemini','Story DNA, audits & images','https://gemini.google.com/app'],['Google AI Studio','Narration with your voice profile','https://aistudio.google.com/generate-speech'],['Google Flow','Motion for your key scenes','https://flow.google.com/']].map(([name,text,url])=><a className="provider-card" href={url} target="_blank" rel="noreferrer" key={name}><span className="provider-initial">{name[0]}</span><div><strong>{name}</strong><span>{tr(text)}</span></div><ExternalLink size={16}/></a>)}</div><ol className="setup-steps"><li><strong>{tr("Open your browser's extension page")}</strong><p><code>edge://extensions</code> {tr("or ")}<code>chrome://extensions</code></p></li><li><strong>{tr("Enable Developer mode → Load unpacked")}</strong><p>{tr("Select the ")}<code>browser-extension</code> {tr("folder beside the app. The installer also creates an “Install / Reload Browser Bridge” shortcut.")}</p></li><li><strong>{tr("Pair the extension with this workspace")}</strong><p>{tr("Generate a local pairing key below, then paste it in the extension popup.")}</p></li><li><strong>{tr("Sign in to your providers normally")}</strong><p>{tr("In the extension, enable automatic sending and capture for waiting ChatGPT/Gemini text jobs. Keep the browser and app open. Turn automation off to use Open tab → Fill → Send / Run → Capture manually.")}</p></li></ol><Button primary onClick={async()=>{const r=await act(()=>api('/settings/pair-bridge','POST'),'New bridge pairing key generated');if(r)setPair(r.token)}}><Radio size={16}/>{tr("Generate pairing key")}</Button>{pair&&<div className="pair-token"><code>{pair}</code><CopyButton text={pair}/></div>}<div className="notice compact">{tr("If a page changes, the job waits for you. Copy the prompt and paste the provider result in Activity & jobs. Login, CAPTCHA, quotas and downloads remain under your control.")}</div></Section><Section title={tr("Connection preferences")}><div className="form-grid"><Field label={tr("Preferred browser")}><select value={form.browser} onChange={e=>set('browser',e.target.value)}><option value="edge">{tr("Microsoft Edge")}</option><option value="chrome">{tr("Google Chrome")}</option></select></Field><Field label={tr("Browser timeout (seconds)")}><input type="number" min="30" max="1800" value={form.browser_timeout} onChange={e=>set('browser_timeout',+e.target.value)}/></Field></div><Button onClick={()=>act(()=>api('/settings','PATCH',form),'Browser preferences saved')}>{tr("Save preferences")}</Button></Section></>}
  {tab==='Prompt templates'&&<Section title={tr("Your process, in your words")} caption={tr("Custom templates are stored in the data folder. Every AI artifact records the template hash.")}><div className="inline between"><select aria-label={tr("Prompt template")} value={promptName} onChange={e=>setPromptName(e.target.value)}>{prompts?.items.map((p:Row)=><option key={p.name} value={p.name}>{label(p.name)}{p.customized?tr(" · customized"):''}</option>)}</select><div className="inline"><Button onClick={async()=>{const r=await act(()=>api('/prompts/'+promptName,'PUT',{text:promptText,restore:true}),'Default restored');if(r)setPromptText(r.text)}}>{tr("Restore default")}</Button><Button primary onClick={()=>act(()=>api('/prompts/'+promptName,'PUT',{text:promptText}),'Prompt saved')}><Save size={15}/>{tr("Save template")}</Button></div></div><textarea className="code-editor prompt-editor" aria-label={tr("Prompt text")} value={promptText} onChange={e=>setPromptText(e.target.value)}/></Section>}
  {tab==='Backup & storage'&&<><Section title={tr("A workspace that belongs to you")} caption={tr("Data is local. Move it to another drive whenever you need.")}><Field label={tr("Data root")}><input value={dataPath} onChange={e=>setDataPath(e.target.value)}/></Field><Button disabled={dataPath===settings.data_root} onClick={()=>act(()=>api('/settings/data-root','POST',{path:dataPath}),'Data copied. Restart StoryForge to use the new location.')}>{tr("Copy workspace & change data root")}</Button><p className="muted">{tr("Original files are preserved. Close and restart the app immediately after changing the data root.")}</p><div className="inline wrap"><a className="button" href="/api/backup"><Database size={16}/>{tr("Back up database")}</a><label className="button"><Upload size={16}/>{tr("Restore database")}<input hidden type="file" accept=".db,.sqlite" onChange={async e=>{const file=e.target.files?.[0];if(!file)return;if(!window.confirm(tr("Restore this database on the next restart? The current database will be backed up first. Imported media must be restored separately."))){e.target.value='';return}const body=new FormData();body.append('file',file);await act(()=>api('/restore','POST',body),'Restore staged for restart');e.target.value=''}}/></label><Button onClick={()=>act(()=>api('/demo','POST'),'Demo workspace loaded')}><Sparkles size={16}/>{tr("Load demo workspace")}</Button></div></Section><Section title={tr("Portable project exports")}><p>{tr("Open a project's Publish tab to export a native CapCut project, a full archive or individual story files.")}</p><div className="notice compact">{tr("Database backups contain metadata and stories. Media stays in the project folders; include media in project archives for a complete portable copy.")}</div></Section></>}
  </>
}
function Logs({version}:{version:number}){const {data,error}=useData('/diagnostics',version,5000);return <><PageHead eyebrow={tr("LOOK UNDER THE HOOD")} title={tr("Logs & diagnostics")} description={tr("Local job and render diagnostics. Passwords, cookies and session credentials are never logged.")} action={<><CopyButton text={pretty(data||{})} caption={tr("Copy diagnostics")}/><a className="button primary" href="/api/diagnostics/export"><Download size={16}/>{tr("Export diagnostics ZIP")}</a></>}/>{!data?<Loading error={error}/>:Object.entries(data.logs).map(([name,text]:any)=><Section key={name} title={name}><pre className="log-output">{text||tr("No events recorded.")}</pre></Section>)}</>}

createRoot(document.getElementById('root')!).render(<React.StrictMode><App/></React.StrictMode>);
